from collections import OrderedDict
from typing import Any, Optional, List, Dict

class LRUCache:
    """A fixed-capacity cache that evicts the least recently used entry."""

    def __init__(self, capacity: int):
        if capacity < 1:
            raise ValueError("Capacity must be greater than or equal to 1.")
        self.capacity = capacity
        self.cache = OrderedDict()

    def get(self, key: Any, default: Optional[Any] = None) -> Any:
        if key not in self.cache:
            return default

        # Move accessed item to the end (most recently used)
        value = self.cache[key]
        self.cache.move_to_end(key)
        return value

    def put(self, key: Any, value: Any) -> Optional[Any]:
        if key in self.cache:
            # Updating an existing key, just move to end
            self.cache[key] = value
            self.cache.move_to_end(key)
            return None

        # Key is new
        if len(self.cache) >= self.capacity:
            # Evict LRU item (the first item in OrderedDict)
            lru_key, _ = self.cache.popitem(last=False)
            return lru_key

        # Insert new item (it goes to the end by default)
        self.cache[key] = value
        return None

    def __len__(self) -> int:
        return len(self.cache)

    def __contains__(self, key: Any) -> bool:
        return key in self.cache

    def keys(self) -> List[Any]:
        # Returns keys from least to most recently used
        return list(self.cache.keys())

    def resize(self, capacity: int) -> List[Any]:
        if capacity < 1:
            raise ValueError("Capacity must be greater than or equal to 1.")

        old_capacity = self.capacity
        self.capacity = capacity
        evicted_keys = []

        # Evict LRU keys until capacity is met
        while len(self.cache) > self.capacity:
            # popitem(last=False) pops the first (LRU) item
            lru_key, _ = self.cache.popitem(last=False)
            evicted_keys.append(lru_key)

        return evicted_keys

