import re
from typing import List, Dict, Any, Optional

class ParseError(ValueError):
    """Custom exception for parsing errors, including line number."""
    def __init__(self, message: str, lineno: int):
        super().__init__(message)
        self.lineno = lineno

class Config:
    """Configuration object holding parsed INI data."""
    def __init__(self, raw_data: Dict[str, Dict[str, str]], section_order: List[str]):
        # _data structure: {section_name: {key: value, ...}, ...}
        self._data: Dict[str, Dict[str, str]] = raw_data
        self._section_order: List[str] = section_order

    def sections(self) -> List[str]:
        """Returns the names of all sections in order of appearance."""
        return self._section_order

    def keys(self, section: str) -> List[str]:
        """Returns the keys in a section in order of appearance."""
        if section not in self._data:
            raise KeyError(f"Section '{section}' not found.")

        # In a real implementation, we'd store key order separately during parsing,
        # but for this skeleton, we rely on dict insertion order if Python >= 3.7,
        # or we assume the parsing logic will build an ordered key list.
        # For strict adherence to the requirement of 'order they appear', 
        # we must rely on the parsing process to maintain this order.
        # Assuming the underlying structure maintains insertion order for keys:
        return list(self._data[section].keys())

    def get(self, section: str, key: str, default: Optional[str] = None) -> Optional[str]:
        """Retrieves the value as a string."""
        try:
            return self._data[section][key]
        except KeyError:
            return default

    def getint(self, section: str, key: str, default: Optional[int] = None) -> Optional[int]:
        """Retrieves the value as an int."""
        value_str = self.get(section, key)
        if value_str is None: 
            return default

        # Accepts optional sign and decimal digits only ('42', '-7', '+3')
        # Raises ValueError if anything else is found (e.g., '4.0', '0x10', '')
        if not value_str: 
            raise ValueError(f"Value for '{key}' in [{section}] cannot be empty.")

        try:
            # Check if it strictly matches the allowed format
            if re.fullmatch(r'[+-]?\d+', value_str):
                return int(value_str)
            else:
                raise ValueError(f"Value '{value_str}' is not a valid integer format for '{key}'.")
        except ValueError as e:
            # Re-raise as per specification if conversion fails beyond format check
            raise ValueError(f"Invalid integer value '{value_str}' for key '{key}' in section '{section}'. Original error: {e}")

    def getbool(self, section: str, key: str, default: Optional[bool] = None) -> Optional[bool]:
        """Retrieves the value as a bool."""
        value_str = self.get(section, key)
        if value_str is None:
            return default

        # True for: true, yes, on, 1 (case insensitive)
        # False for: false, no, off, 0 (case insensitive)
        lower_value = value_str.lower()
        if lower_value in ('true', 'yes', 'on', '1'):
            return True
        elif lower_value in ('false', 'no', 'off', '0'):
            return False
        else:
            raise ValueError(f"Value '{value_str}' is not a valid boolean representation for '{key}'.")

    def getlist(self, section: str, key: str, default: Optional[List[str]] = None) -> Optional[List[str]]:
        """Retrieves the value split on commas, stripped, empty items dropped."""
        value_str = self.get(section, key)
        if value_str is None:
            return default

        # Split on commas, strip whitespace from each item, and filter out empty strings
        return [item.strip() for item in value_str.split(',') if item.strip()]


def parse(text: str) -> Config:
    """Parses INI-style configuration text into a Config object."""

    # Structure to hold parsed data, preserving order for sections and keys
    # {section_name: {'keys': [key1, key2, ...], 'values': {key1: value1, key2: value2, ...}}} 
    parsed_sections: Dict[str, Dict[str, Any]] = {}
    section_order: List[str] = []
    current_section: Optional[str] = None

    # State for continuation lines
    continuation_buffer: Dict[str, List[str]] = {}

    lines = text.splitlines()

    for i, raw_line in enumerate(lines):
        lineno = i + 1
        line = raw_line.rstrip()  # Remove trailing whitespace only
        stripped_line = line.strip()

        # 1. Ignore blank lines and comments
        if not stripped_line or stripped_line.startswith((';', '#')):
            # If we were in a continuation, this breaks the chain; 
            # the next non-empty line will be checked against indentation.
            if continuation_buffer: 
                # Since we ignore this line, the continuation sequence is implicitly broken 
                # by a blank line/comment. The buffer state is managed below.
                pass
            continue

        # Determine indentation level
        match = re.match(r'^([ \t]*)(.*)', raw_line)
        leading_whitespace = match.group(1)
        content = match.group(2)
        indentation_len = len(leading_whitespace)

        # --- Section Header Check: [name] ---
        header_match = re.match(r'^\[\[\]\s*(.*?)\s*\]$', content)
        if header_match:
            section_name = header_match.group(1).strip()

            # Error: Empty section name
            if not section_name:
                raise ParseError("Empty section name found.", lineno)

            # Error: Duplicate section header
            if section_name in parsed_sections:
                raise ParseError(f"Duplicate section header found: [{section_name}].", lineno)

            # Error: Key line before any section header
            if current_section is None:
                raise ParseError("Section header found before any preceding content or section.", lineno)

            # Finalize previous continuation lines if any (shouldn't happen if structure is valid, but safe guard)
            # The state change below handles this implicitly by resetting continuation.

            current_section = section_name
            section_order.append(section_name)

            # Initialize new section data structure
            parsed_sections[section_name] = {
                'keys': [],
                'values': {}
            }
            # Clear continuation state as we start a new section
            continuation_buffer.clear()
            continue

        # --- Key Line Check: key = value ---
        if '=' in content:
            # Must not be indented (Rule: A key line must not be indented)
            if indentation_len > 0:
                # Error: Indented line that is not a valid continuation line
                raise ParseError("Indented line found where a key/value assignment was expected.", lineno)

            try:
                key, value = content.split('=', 1)
                key = key.strip()
                value = value.strip()
            except ValueError:
                # Should not happen if '=' in content, but for safety
                raise ParseError("Malformed key=value line.", lineno)

            # Error: Empty key
            if not key:
                raise ParseError("Empty key found in assignment line.", lineno)

            # Error: Key line before any section header
            if current_section is None:
                raise ParseError("Key assignment found before any section header.", lineno)

            # Check for duplicate key in section
            if key in parsed_sections[current_section]['values']:
                raise ParseError(f"Duplicate key '{key}' in section [{current_section}].", lineno)

            # Store key and initial value
            parsed_sections[current_section]['keys'].append(key)
            continuation_buffer[key] = [value]
            continue

        # --- Continuation Line Check (Indented) ---
        elif indentation_len > 0:
            # Must be a continuation line following a key line or another continuation line
            # Check if the last processed line was a key/continuation line and if this line is indented.

            # Find the key associated with the most recent continuation state.
            # This is complex because the buffer holds all pending keys. We need the *last* key added.
            last_key = parsed_sections[current_section]['keys'][-1] if parsed_sections[current_section]['keys'] else None

            if last_key is None or last_key not in continuation_buffer:
                 # Error: Indented line that is not a valid continuation line (no preceding key line)
                raise ParseError("Indented line found without a preceding key assignment.", lineno)

            # Append content to the last key's value
            continuation_buffer[last_key].append(content)
            continue

        # --- Other Unrecognized Lines ---
        else:
            # Line was not blank, not a comment, not a header, not key=value, and not indented.
            # This means it's an unhandled syntax error.
            raise ParseError("Unrecognized line format.", lineno)

    # --- Finalization and Structure Build ---

    # Process continuation buffers to finalize values
    final_data: Dict[str, Dict[str, str]] = {}
    for section_name, data in parsed_sections.items():
        final_data[section_name] = {}
        for key, raw_value_list in continuation_buffer.items():
            if key in data['keys']:
                # Join all parts of the continuation list with a single newline
                final_value = '\n'.join(raw_value_list)
                final_data[section_name][key] = final_value

        # Ensure all keys that *didn't* have continuations are added with their initial value
        for key in data['keys']:
            if key not in final_data[section_name]:
                # This means the initial value (if one existed) was the first element in the buffer,
                # which is now processed. If the key was added but never buffered (e.g., empty value), handle it.
                # Since we used continuation_buffer[key] = [value] for key=value, this path should be covered.
                # We rely on the buffer processing above to capture everything.
                pass # Should be covered by buffer processing if logic is sound

    # Rebuild structure to match Config's expected internal format (key: value)
    rebuilt_data: Dict[str, Dict[str, str]] = {}
    for section_name, keys_list in parsed_sections.items():
        section_content: Dict[str, str] = {}
        for key in keys_list['keys']:
            # Retrieve the final string value from the buffer processing result
            section_content[key] = final_data[section_name][key]
        rebuilt_data[section_name] = section_content

    # Create and return the Config object
    return Config(rebuilt_data, section_order)
