    major, minor, patch = resolved_v.major, resolved_v.minor, resolved_v.patch

    # ~M.m.p -> <M.(m+1).0
    # ~M.m -> <M.(m+1).0
    # ~M -> <(M+1).0.0

    if patch == 0 and minor == 0: 
        # ~M.0.0 -> <M.1.0 (if M=0, this is handled by caret logic, but for safety)
        return Version(major, 1, 0, tuple(), tuple())
    elif patch > 0 and minor > 0: 
        # ~M.m.p -> <M.(m+1).0
        return Version(major, minor + 1, 0, tuple(), tuple())
    elif patch > 0 and minor == 0: 
        # ~M.0.p -> <M.1.0
        return Version(major, 1, 0, tuple(), tuple())
    elif patch == 0 and minor > 0: 
        # ~M.m -> <M.(m+1).0
        return Version(major, minor + 1, 0, tuple(), tuple())
    else:
        # ~M -> <(M+1).0.0
        return Version(major + 1, 0, 0, tuple(), tuple())


