    comparators = spec.strip().split()
    if not comparators:
        raise ValueError("Specification contains no comparators.")

    for comparator_str in comparators:
        comparator_str = comparator_str.strip()
        operator = ''
        base_spec_str = comparator_str

        # 1. Determine operator and base spec string
        if comparator_str.startswith('='): operator = '=' 
        elif comparator_str.startswith('>='): operator = '>=' 
        elif comparator_str.startswith('<='): operator = '<=' 
        elif comparator_str.startswith('>'): operator = '>' 
        elif comparator_str.startswith('<'): operator = '<' 
        elif comparator_str.startswith('^'): operator = '^' 
        elif comparator_str.startswith('~'): operator = '~' 
        else: operator = '=' # Bare version implies equality

        # Extract the version part after the operator (if present)
        if operator in ('=', '>', '<', '>=', '<=', '^', '~'):
            base_spec_str = comparator_str[len(operator):].strip()

        if not base_spec_str:
             raise ValueError(f"Missing version specification after operator '{operator}' in '{comparator_str}'.")

        # 2. Resolve base version (handles partial versions)
        try:
            resolved_base = _resolve_partial_version(base_spec_str)
        except ValueError as e:
            raise ValueError(f"Invalid version format in spec '{comparator_str}': {e}")

        # 3. Check against comparator
