                constraint_version = resolved_base
                if not (version == constraint_version):
                    return False
            elif operator == '>':
                # Standard comparison
                constraint_version = resolved_base
                if not (version > constraint_version):
                    return False
            elif operator == '<':
                constraint_version = resolved_base
                if not (version < constraint_version):
                    return False
            elif operator == '>=':
                constraint_version = resolved_base
                if not (version >= constraint_version):
                    return False
            elif operator == '<=':
                constraint_version = resolved_base
                if not (version <= constraint_version):
                    return False
            elif operator == '^':
                # ^V is equivalent to >=V and <Upper_Bound
                lower_bound = resolved_base
                upper_bound = _calculate_caret_bound(resolved_base)

                if not (version >= lower_bound and version < upper_bound):
                    return False
            elif operator == '~':
                # ~V is equivalent to >=V and <Next_Minor_Bound
                lower_bound = resolved_base
                upper_bound = _calculate_tilde_bound(resolved_base)

                if not (version >= lower_bound and version < upper_bound):
                    return False
        except TypeError:
             # Catches cases where version/constraint might not support comparison (e.g., mixing Version with str)
             raise ValueError(f"Comparison error: Cannot compare {type(version)} with constraint derived from {comparator_str}.")

    return True

