        # 1. Compare MAJOR, MINOR, PATCH numerically
        if self.major != other.major:
            return self.major < other.major
        if self.minor != other.minor:
            return self.minor < other.minor
        if self.patch != other.patch:
            return self.patch < other.patch

        # 2. Compare pre-release tags
        if self.prerelease and not other.prerelease:
            # Pre-release is lower than release version
            return True
        if not self.prerelease and other.prerelease:
            # Release version is higher than pre-release
            return False

        # Both have pre-release tags or both don't
        if self.prerelease and other.prerelease:
            return self._compare_prerelease(other.prerelease) < 0

        # Both are final versions and major/minor/patch matched
        return False # They are equal

    def __le__(self, other) -> bool:
        if not isinstance(other, Version):
            return NotImplemented
        return self < other or self == other

    def __gt__(self, other) -> bool:
        if not isinstance(other, Version):
            return NotImplemented
        return not (self <= other)

    def __ge__(self, other) -> bool:
        if not isinstance(other, Version):
            return NotImplemented
        return not (self < other)

    def __ne__(self, other) -> bool:
        return not self.__eq__(other)

    # --- Bumping Logic ---

    def bump(self, kind: str) -> 'Version':
        """Returns a new version bumped by the specified kind.

        Raises ValueError if the kind is invalid or if the current version is a pre-release/build.
        """
        # Requirement: The result never has a pre-release or build part
        if self.prerelease or self.build: 
            raise ValueError("Cannot bump a pre-release or build version directly. Bumped versions are final releases.")

        if kind == 'major':
            new_version = Version(self.major + 1, 0, 0, tuple(), tuple(), self._original_text)
        elif kind == 'minor':
            new_version = Version(self.major, self.minor + 1, 0, tuple(), tuple(), self._original_text)
        elif kind == 'patch':
            new_version = Version(self.major, self.minor, self.patch + 1, tuple(), tuple(), self._original_text)
        else:
            raise ValueError(f"Invalid bump kind: {kind}. Must be 'major', 'minor', or 'patch'.")

        return new_version

    # --- Range Satisfaction Logic ---

    @staticmethod
    def _parse_partial_version(v_str: str) -> 'Version':
        """Parses a partial version string (e.g., '1.2' -> 1.2.0) into a full Version object, ignoring pre-release/build for partial specs.
        """
        parts = v_str.split('.')
        if len(parts) > 3 or len(parts) < 1:
            raise ValueError(f"Invalid partial version format: {v_str}")

        try:
            major = int(parts[0])
            minor = int(parts[1]) if len(parts) > 1 else 0
            patch = int(parts[2]) if len(parts) > 2 else 0
        except ValueError:
            raise ValueError(f"Partial version components must be integers: {v_str}")

        if '-' in v_str or '+' in v_str:
            raise ValueError("Partial version specifiers cannot contain pre-release or build metadata.")

        # Create a dummy version object representing the resolved full version
        # Since this is derived from a partial spec, pre/build are empty.
        return Version(major, minor, patch, tuple(), tuple(), f"Resolved_{v_str}")

    @staticmethod
    def _get_upper_bound_for_caret(v: 'Version') -> 'Version':
        """Calculates the exclusive upper bound for ^V.
        ^1.2.3 -> <2.0.0
        ^0.2.3 -> <0.3.0
        ^0.0.3 -> <0.0.4
        """
        M, m, p = v.major, v.minor, v.patch

        if M > 0:
            # Standard increment: (M+1).0.0
            return Version(M + 1, 0, 0, tuple(), tuple(), f"^Bound_{v}")
        elif m > 0:
            # Minor increment: 0.(m+1).0
            return Version(0, m + 1, 0, tuple(), tuple(), f"^Bound_{v}")
        else: # M=0 and m=0
            # Patch increment: 0.0.(p+1)
            return Version(0, 0, p + 1, tuple(), tuple(), f"^Bound_{v}")

    @staticmethod
    def _get_upper_bound_for_tilde(v: 'Version') -> 'Version':
        """Calculates the exclusive upper bound for ~V.
        ~1.2.3 -> <1.3.0
        ~1.2 -> <1.3.0
        ~1 -> <2.0.0
        """
        M, m, p = v.major, v.minor, v.patch

        if p > 0:
            # Patch increment: M.m.(p+1)
            return Version(M, m, p + 1, tuple(), tuple(), f"~Bound_{v}")
        elif m > 0:
            # Minor increment: M.(m+1).0
            return Version(M, m + 1, 0, tuple(), tuple(), f"~Bound_{v}")
        else: # M > 0 and m=0 and p=0
            # Major increment: (M+1).0.0
            return Version(M + 1, 0, 0, tuple(), tuple(), f"~Bound_{v}")

    @staticmethod
    def _check_satisfaction(version: 'Version', spec_part: str) -> bool:
        """Checks if a Version satisfies a single spec part.
        """
        spec_part = spec_part.strip()
        if not spec_part:
            return False

        op = None
        version_str = spec_part
        is_range_operator = False

        # Check for comparison operators
        if spec_part.startswith('>='): op = '>=' ; version_str = spec_part[2:]
        elif spec_part.startswith('>'): op = '>' ; version_str = spec_part[1:]
        elif spec_part.startswith('<='): op = '<=' ; version_str = spec_part[2:]
        elif spec_part.startswith('<'): op = '<' ; version_str = spec_part[1:]
        elif spec_part.startswith('='): op = '=' ; version_str = spec_part[1:]
        elif spec_part.startswith('~'): op = '~' ; version_str = spec_part[1:]
        elif spec_part.startswith('^'): op = '^' ; version_str = spec_part[1:]
        else: op = '=' # Bare version implies equality

        try:
            if op == '=' or op is None: 
                # Handle bare version or explicit equality
                # Check if the spec is partial or full
                if '.' in version_str and not all(c.isdigit() or c == '.' for c in version_str) and ('-' in version_str or '+' in version_str):
                    # This case implies a malformed spec like '1.2-a' used as equality
                    raise ValueError("Equality specifiers cannot include pre-release or build metadata.")

                try:
                    # Try parsing as full version first (for strict equality checks)
                    target_v = Version.parse(version_str)
                    return version == target_v
                except ValueError:
                    # If parsing as full version fails, it must be a partial version specifier
                    # We resolve the partial version and check equality against the resolved version.
                    target_v = Version._parse_partial_version(version_str)
                    return version == target_v

            elif op in ('~', '^'):
                # Range Operators: V must be resolved to a base version first

                # 1. Resolve the spec string to a base Version object (M.m.p)
                try:
                    base_v = Version._parse_partial_version(version_str)
                except ValueError:
                    # If partial parsing fails, it might be a full version that failed strict parsing earlier,
                    # or it is invalid.
                    raise ValueError(f"Cannot resolve base version for range operator '{op}': {version_str}")

                # 2. Calculate exclusive upper bound
                if op == '^':
                    upper_bound = Version._get_upper_bound_for_caret(base_v)
                else: # op == '~'
                    upper_bound = Version._get_upper_bound_for_tilde(base_v)

                # 3. Check lower bound (inclusive) and upper bound (exclusive)
                # Lower bound is always >= base_v
                lower_bound = base_v

                # Check lower bound: version >= base_v
                if version < lower_bound:
                    return False

                # Check upper bound: version < upper_bound
                return version < upper_bound

            else: # >, <, >=, <= (Standard comparison)
                # For standard operators, we must parse the target version.
                # Partial versions are only allowed for equality checks, but if present with operators,
                # we resolve them to the full version for comparison.
                try:
                    target_v = Version.parse(version_str)
                except ValueError:
                    # If parsing as full version fails, resolve as partial.
                    target_v = Version._parse_partial_version(version_str)

                if op == '>=': return version >= target_v
                if op == '>': return version > target_v
                if op == '<=': return version <= target_v
                if op == '<': return version < target_v

        except ValueError as e:
            raise ValueError(f"Invalid version specifier '{spec_part}' in comparator: {e}")

        return False

    @staticmethod
    def satisfies(version: 'Version', spec: str) -> bool:
        """Checks if a version satisfies a space-separated list of comparators.
        """
        if not spec or not spec.strip():
            raise ValueError("Version specification cannot be empty.")

        comparators = spec.split()

        for comparator in comparators:
            if not Version._check_satisfaction(version, comparator):
                return False

        return True

from datetime import date
from typing import Iterable

def is_business_day(d: date, *, holidays: Iterable[date] = (), weekend: Iterable[int] = (5, 6)) -> bool:
    """Checks if a given date is a business day.

    A business day is a date whose weekday (Monday=0 to Sunday=6) is not in `weekend` 
    and that is not in `holidays`.

    :param d: The date to check.
    :param holidays: An iterable of holiday dates.
    :param weekend: An iterable of weekday numbers representing weekends (e.g., (5, 6) for Sat/Sun).
    :return: True if the date is a business day, False otherwise.
    """
    if d in holidays:
        return False
    if d.weekday() in weekend:
        return False
    return True

def business_days_between(start: date, end: date, *, include_start: bool = True, include_end: bool = False, holidays: Iterable[date] = (), weekend: Iterable[int] = (5, 6)) -> int:
    """Counts the number of business days between two dates.

    :param start: The starting date.
    :param end: The ending date.
    :param include_start: Whether to count the start date.
    :param include_end: Whether to count the end date.
    :param holidays: An iterable of holiday dates.
    :param weekend: An iterable of weekday numbers representing weekends.
    :raises ValueError: If start date is after end date.
    :return: The number of business days in the range.
    """
    if start > end:
        raise ValueError("Start date cannot be after end date.")

    count = 0
    current_day = start

    while current_day <= end:
        is_business = is_business_day(current_day, holidays=holidays, weekend=weekend)

        if is_business:
            if include_start and current_day == start:
                count += 1
            elif include_end and current_day == end:
                count += 1
            elif current_day > start and current_day < end:
                count += 1

        if current_day == end:
            break
        current_day = date.fromordinal(current_day.toordinal() + 1)

    # Handle the specific case where start == end
    if start == end:
        if is_business_day(start, holidays=holidays, weekend=weekend):
            return 1 if include_start and include_end else (1 if include_start else 0)
        else:
            return 0

    # Recalculate count carefully based on logic to ensure correctness for ranges
    count = 0
    current_day = start
    while current_day <= end:
        is_business = is_business_day(current_day, holidays=holidays, weekend=weekend)

        if is_business:
            if current_day == start and include_start:
                count += 1
            elif current_day == end and include_end:
                count += 1
            elif current_day > start and current_day < end:
                count += 1

        current_day = date.fromordinal(current_day.toordinal() + 1)

    return count

def add_business_days(d: date, n: int, *, holidays: Iterable[date] = (), weekend: Iterable[int] = (5, 6)) -> date:
    """Calculates a date after or before a given date by a specified number of business days.

    :param d: The starting date.
    :param n: The number of business days to add (positive) or subtract (negative).
    :param holidays: An iterable of holiday dates.
    :param weekend: An iterable of weekday numbers representing weekends.
    :return: The resulting date.
    :raises ValueError: If the initial weekend configuration allows no working days.
    """

    # Check if any weekday is a working day
    working_days = set(range(7)) - set(weekend)
    if not working_days:
         raise ValueError("Weekend configuration excludes all working days.")

    if n > 0:
        current_day = d
        days_added = 0
        while days_added < n:
            current_day = date.fromordinal(current_day.toordinal() + 1)
            if is_business_day(current_day, holidays=holidays, weekend=weekend):
                days_added += 1
        return current_day

    elif n < 0:
        current_day = d
        days_subtracted = 0
        while days_subtracted < abs(n):
            current_day = date.fromordinal(current_day.toordinal() - 1)
            if is_business_day(current_day, holidays=holidays, weekend=weekend):
                days_subtracted += 1
        return current_day

    else: # n == 0
        if is_business_day(d, holidays=holidays, weekend=weekend):
            return d
        else:
            # Find the first business day AFTER d
            current_day = date.fromordinal(d.toordinal() + 1)
            while not is_business_day(current_day, holidays=holidays, weekend=weekend):
                current_day = date.fromordinal(current_day.toordinal() + 1)
            return current_day

