from fsm import Machine, MachineError
from typing import Dict, Tuple, List, Optional
from collections import defaultdict

# --- Vending Errors ---
class VendingError(MachineError):
    """Base class for vending machine errors, inheriting from FSM errors."""
    pass

class SoldOut(VendingError):
    """Raised when a product is out of stock."""
    pass

class InsufficientCredit(VendingError):
    """Raised when credit is insufficient for the selected product."""
    pass

# --- Helper Functions ---

def calculate_change(credit: int, price: int, accepted_coins: Tuple[int, ...] = (100, 25, 10, 5)) -> List[int]:
    """Greedily calculates change in coins."""
    change_due = credit - price
    change_coins: List[int] = []

    for coin_value in accepted_coins:
        while change_due >= coin_value:
            change_coins.append(coin_value)
            change_due -= coin_value

    return change_coins

# --- Vending Machine Class ---

class VendingMachine:
    """A vending machine built on an FSM."""
    def __init__(self, products: Dict[str, Tuple[int, int]]):
        # products: {code: (price_cents, stock)}
        self.products = products
        # We need to track initial stock/prices for reference/restock logic
        self.initial_products_state = {code: stock for code, (_, stock) in products.items()}
        self.initial_prices = {code: price for code, (price, _) in products.items()}

        # State and Context
        self.credit: int = 0
        self.sales: Dict[str, int] = defaultdict(int)
        self.revenue: int = 0
        # Internal mutable stock state
        self._stock: Dict[str, int] = self.initial_products_state.copy()

        # FSM Setup
        self.states = ["idle", "credit", "maintenance"]
        self.transitions: List[Transition] = []
        self._setup_transitions()

        self.machine = Machine(states=self.states, transitions=self.transitions, initial="idle", context=self)

    def _setup_transitions(self):
        # Events: insert_coin, select_product, cancel, service, restock, resume

        # 1. Idle -> Credit (via insert_coin)
        self.transitions.append(Transition(
            event="insert_coin",
            source="idle",
            target="credit"
        ))

        # 2. Credit -> Idle (via select_product, if successful)
        # The guard handles the logic (KeyError, SoldOut, InsufficientCredit)
        self.transitions.append(Transition(
            event="select_product",
            source="credit",
            target="idle",
            guard=self._can_select
        ))

        # 3. Credit -> Idle (via cancel)
        self.transitions.append(Transition(
            event="cancel",
            source="credit",
            target="idle"
        ))

        # 4. Idle -> Maintenance (via service)
        self.transitions.append(Transition(
            event="service",
            source="idle",
