from dataclasses import dataclass, field
from typing import List, Tuple, Dict, Optional, Any, Union
import copy

# --- Exceptions ---

class MachineError(Exception):
    """The base class for machine errors."""
    pass

class InvalidTransition(MachineError):
    """Raised when no transition matches the event from the current state."""
    def __init__(self, state: str, event: str):
        self.state = state
        self.event = event
        super().__init__(f"Invalid transition: no transition for event '{event}' from state '{state}'.")

class GuardRejected(MachineError):
    """Raised when all transitions for an event are rejected by their guards."""
    def __init__(self, state: str, event: str):
        self.state = state
        self.event = event
        super().__init__(f"Guard rejected: all transitions for event '{event}' from state '{state}' were rejected.")

# --- Data Classes ---

@dataclass
class State:
    name: str
    on_enter: Optional[callable] = None
    on_exit: Optional[callable] = None

@dataclass
class Transition:
    event: str
    source: Union[str, List[str], Tuple[str, ...]]
    target: Optional[str]
    guard: Optional[callable] = None
    action: Optional[callable] = None

@dataclass
class Event:
    name: str
    source: str
    target: str
    data: Dict[str, Any]

# --- Machine Class ---

class Machine:
    """Finite State Machine implementation."""
    def __init__(self, states: Union[List[State], List[str]], transitions: List[Transition], initial: str, context: Optional[Any] = None):
        self.context: Any = context
        self._initial_state = initial
        self._states: Dict[str, State] = {}
        self._transitions: List[Transition] = transitions
        self._history: List[Tuple[str, str, str]] = []
        self.on_transition_listeners: List[callable] = []

        self._initialize_states(states)

        if initial not in self._states:
            raise ValueError(f"Initial state '{initial}' is not a defined state.")

        self.state: str = initial

    def _initialize_states(self, states_input: Union[List[State], List[str]]):
        state_names = set()
        for item in states_input:
            name = item.name if isinstance(item, State) else item
            if name in state_names:
                raise ValueError(f"State name '{name}' is duplicated.")

            if isinstance(item, State):
                self._states[name] = item
            else:
                # Plain name, create state object
                self._states[name] = State(name=name)

            state_names.add(name)

        # Validate transitions against defined states
        all_defined_states = set(self._states.keys())
        for t in self._transitions:
            # Check source
            source_valid = False
            if t.source == '*':
                source_valid = True
            elif isinstance(t.source, str) and t.source in all_defined_states:
                source_valid = True
            elif isinstance(t.source, (list, tuple)) and any(s in all_defined_states for s in t.source):
                source_valid = True

            if not source_valid:
                raise ValueError(f"Transition references undefined source state(s) in '{t.source}'.")

            # Check target
            if t.target is not None and t.target not in all_defined_states:
                raise ValueError(f"Transition references undefined target state '{t.target}'.")

    def fire(self, event_name: str, **data: Any) -> str:
        """Processes an event and transitions the machine."""
        # Rule 7: Check for recursive fire
        if getattr(self, '_is_firing', False):
            raise MachineError("Cannot call fire while another fire operation is in progress.")

        self._is_firing = True
        new_state = self.state
        transition_taken: Optional[Transition] = None

        # 1. Find candidates
        candidates: List[Transition] = []
        current_state_name = self.state

        # Determine matching source states
        source_matches: List[str] = []
        if current_state_name == '*':
             source_matches = list(self._states.keys())
        elif isinstance(current_state_name, str) and current_state_name in self._states:
             source_matches = [current_state_name]
        else:
             # Should not happen if state is valid
             self._is_firing = False
             raise MachineError(f"Current state '{current_state_name}' is invalid.")

        for t in self._transitions:
            if t.event != event_name:
                continue

            # Check source match
            source_match = False
            if t.source == '*':
                source_match = True
            elif isinstance(t.source, str) and t.source in source_matches:
                source_match = True
            elif isinstance(t.source, (list, tuple)) and any(s in source_matches for s in t.source):
                source_match = True

            if source_match:
                candidates.append(t)

        if not candidates:
            self._is_firing = False
            raise InvalidTransition(current_state_name, event_name)

        # 2. Create event data dictionary (shared across all hooks in this call)
        event_data = data.copy()

        # 3. Evaluate guards
        chosen_transition: Optional[Transition] = None
        for t in candidates:
            if t.guard is None:
                chosen_transition = t
                break

            try:
                # Guard must not have side effects; evaluate it.
                if t.guard(self, event_data):
                    chosen_transition = t
                    break
            except Exception as e:
                # If a guard raises an exception, it propagates unchanged.
                self._is_firing = False
                raise e

        if chosen_transition is None:
            self._is_firing = False
            raise GuardRejected(current_state_name, event_name)

        transition_taken = chosen_transition
        next_state_name = transition_taken.target if transition_taken.target is not None else current_state_name

        # --- State Transition Logic ---

        try:
            # 4. & 5. Execute hooks and state change

            # 4. Normal transition sequence:
            if transition_taken.target is not None:
                # Normal transition

                # Run current state's on_exit
                if self._states[current_state_name].on_exit:
                    self._states[current_state_name].on_exit(self, event_data)

                # Run transition's action
                if transition_taken.action:
                    transition_taken.action(self, event_data)

                # Set state and append to history
                self.state = next_state_name
                self._history.append((current_state_name, event_name, next_state_name))

                # Run target state's on_enter
                if self._states[next_state_name].on_enter:
                    self._states[next_state_name].on_enter(self, event_data)

            else:
                # Internal transition (target=None)
                # Runs only action, records history, calls listeners. No on_exit/on_enter.
                if transition_taken.action:
                    transition_taken.action(self, event_data)

                self._history.append((current_state_name, event_name, current_state_name))

            # Run listeners (in order added)
            for listener in self.on_transition_listeners:
                listener(current_state_name, event_name, next_state_name)

        except MachineError as e:
            # 6. Exception propagation (Internal MachineError)
            # If the error originated in a guard, it propagated immediately above. 
            # If it comes from on_exit/action, state/history are unchanged. If it comes from on_enter/listener, state has changed.
            self._is_firing = False
            raise e

        except Exception as e:
            # 6. Any other exception propagates unchanged out of fire.
            self._is_firing = False
            raise e

        self._is_firing = False
        return self.state

    def can_fire(self, event_name: str, **data: Any) -> bool:
        """Checks if a transition is possible without running hooks."""
        current_state_name = self.state
        candidates: List[Transition] = []

        source_matches: List[str] = []
        if current_state_name == '*':
             source_matches = list(self._states.keys())
        elif isinstance(current_state_name, str) and current_state_name in self._states:
             source_matches = [current_state_name]

        for t in self._transitions:
            if t.event != event_name:
                continue

            # Check source match
            source_match = False
            if t.source == '*':
                source_match = True
            elif isinstance(t.source, str) and t.source in source_matches:
                source_match = True
            elif isinstance(t.source, (list, tuple)) and any(s in source_matches for s in t.source):
                source_match = True

            if source_match:
                candidates.append(t)

        if not candidates:
            return False

        # Check guards
        for t in candidates:
            if t.guard is None:
                return True

            try:
                if t.guard(self, data):
                    return True
            except Exception:
                # Treat exception during can_fire check as non-matching for safety, although guards should be pure
                pass 

        return False

    def available_events(self) -> List[str]:
        """Returns sorted, de-duplicated names of available events."""
        available: set[str] = set()
        current_state_name = self.state

        source_matches: List[str] = []
        if current_state_name == '*':
             source_matches = list(self._states.keys())
        elif isinstance(current_state_name, str) and current_state_name in self._states:
             source_matches = [current_state_name]

        for t in self._transitions:
            # Check source match
            source_match = False
            if t.source == '*':
                source_match = True
            elif isinstance(t.source, str) and t.source in source_matches:
                source_match = True
            elif isinstance(t.source, (list, tuple)) and any(s in source_matches for s in t.source):
                source_match = True

            if source_match:
                available.add(t.event)

        return sorted(list(available))

    def on_transition(self, listener: callable):
        """Adds a listener function to be called after any successful transition."""
        self.on_transition_listeners.append(listener)

    def reset(self):
        """Resets the machine state to initial and clears history without running hooks."""
        self.state = self._initial_state
        self._history = []

    @property
    def _is_firing(self) -> bool:
        return getattr(self, '_is_firing', False)

    @_is_firing.setter
    def _is_firing(self, value: bool):
        self._is_firing = value


