    "MachineError",
    "InvalidTransition",
    "GuardRejected",
]

from fsm import Machine, MachineError
from typing import Dict, Tuple, List, Optional
from collections import defaultdict

# --- Vending Errors ---
class VendingError(MachineError):
    """Base class for vending machine errors, inheriting from FSM errors."""
    pass

class SoldOut(VendingError):
    """Raised when a product is out of stock."""
    pass

class InsufficientCredit(VendingError):
    """Raised when credit is insufficient for the selected product."""
    pass

# --- Helper Functions ---

def calculate_change(credit: int, price: int, accepted_coins: Tuple[int, ...] = (100, 25, 10, 5)) -> List[int]:
    """Greedily calculates change in coins."""
    change_due = credit - price
    change_coins: List[int] = []

    for coin_value in accepted_coins:
        while change_due >= coin_value:
            change_coins.append(coin_value)
            change_due -= coin_value

    return change_coins

# --- Vending Machine Class ---

class VendingMachine:
    """A vending machine built on an FSM."""
    def __init__(self, products: Dict[str, Tuple[int, int]]):
        # products: {code: (price_cents, stock)}
        self.products = products
        # We need to track initial stock/prices for reference/restock logic
        self.initial_products_state = {code: stock for code, (_, stock) in products.items()}
        self.initial_prices = {code: price for code, (price, _) in products.items()}

        # State and Context
        self.credit: int = 0
        self.sales: Dict[str, int] = defaultdict(int)
        self.revenue: int = 0
        # Internal mutable stock state
        self._stock: Dict[str, int] = self.initial_products_state.copy()

        # FSM Setup
        self.states = ["idle", "credit", "maintenance"]
        self.transitions: List[Transition] = []
        self._setup_transitions()

        self.machine = Machine(states=self.states, transitions=self.transitions, initial="idle", context=self)

    def _setup_transitions(self):
        # Events: insert_coin, select_product, cancel, service, restock, resume

        # 1. Idle -> Credit (via insert_coin)
        self.transitions.append(Transition(
            event="insert_coin",
            source="idle",
            target="credit"
        ))

        # 2. Credit -> Idle (via select_product, if successful)
        # The guard handles the logic (KeyError, SoldOut, InsufficientCredit)
        self.transitions.append(Transition(
            event="select_product",
            source="credit",
            target="idle",
            guard=self._can_select
        ))

        # 3. Credit -> Idle (via cancel)
        self.transitions.append(Transition(
            event="cancel",
            source="credit",
            target="idle"
        ))

        # 4. Idle -> Maintenance (via service)
        self.transitions.append(Transition(
            event="service",
            source="idle",
            target="maintenance"
        ))

        # 5. Maintenance -> Idle (via resume)
        self.transitions.append(Transition(
            event="resume",
            source="maintenance",
            target="idle"
        ))

    # --- Internal Guard Logic ---
    def _can_select(self, machine: Machine, event_data: Dict[str, Any]) -> bool:
        # This guard checks for product existence, stock, and sufficient credit.
        code = event_data.get('code')

        if code not in self.initial_prices: # Use initial_prices as the source of truth for known codes
            raise KeyError(f"Product code '{code}' not found.")

        if self._stock.get(code, 0) <= 0:
            raise SoldOut(f"Product {code} is out of stock.")

        price = self.initial_prices[code]

        if self.credit < price:
            raise InsufficientCredit(f"Insufficient credit to buy product {code}. Needed: {price}, Have: {self.credit}.")

        return True

    # --- Public Methods ---

    def insert(self, coin: int) -> int:
        """Adds a coin to the credit, moves to 'credit', returns new credit."""
        if coin not in (5, 10, 25, 100):
            raise ValueError("Coin not accepted by machine.")

        # Attempt to fire the event. The FSM enforces state rules.
        try:
            self.machine.fire("insert_coin", coin=coin)
        except MachineError as e:
            # If FSM blocks the transition (e.g., not in idle/credit state), we respect that and don't change credit.
            if isinstance(e, InvalidTransition):
                return self.credit
            # Re-raise other FSM errors (e.g., recursive fire)
            raise e

        # If successful, update credit
        self.credit += coin
        return self.credit

    def select(self, code: str) -> List[int]:
        """Sells one unit, returns change, moves to 'idle'."""
        if self.machine.state != 'credit':
            # This is defensive, as FSM should handle this via InvalidTransition
            raise MachineError("Cannot select product, machine is not in 'credit' state.")

        try:
            # The guard in _setup_transitions handles KeyError, SoldOut, InsufficientCredit.
            self.machine.fire("select_product", code=code)
        except MachineError as e:
            # A failed selection leaves credit, stock, and state unchanged. The exception is what we return/propagate.
            if isinstance(e, KeyError): raise KeyError(e.args[0]) 
            if isinstance(e, SoldOut): raise SoldOut(e.args[0]) 
            if isinstance(e, InsufficientCredit): raise InsufficientCredit(e.args[0])
            raise e

        # If transition succeeds (state is now 'idle')
        price = self.initial_prices[code]

        # 1. Update stock
        self._stock[code] -= 1
        self.sales[code] += 1
        self.revenue += price

        # 2. Calculate change and return
        change = calculate_change(self.credit, price)

        # 3. Reset credit
        self.credit = 0
        return change

    def cancel(self) -> List[int]:
        """Refunds the whole credit as coins, moves to 'idle'."""
        if self.machine.state != 'credit':
             raise MachineError("Cannot cancel, machine is not in 'credit' state.")

        try:
            self.machine.fire("cancel")
        except MachineError as e:
            raise e

        # Refund logic
        refund = calculate_change(self.credit, 0) # Price 0 to just calculate change from credit
        self.credit = 0
        return refund

