from dataclasses import dataclass, field
from typing import Callable, Optional, List, Dict, Any
from datetime import date

# Assuming these are imported from library/__init__.py or directly from dependencies
from library.catalog import Catalog
from library.fines import POLICY, Policy, HOLD_PICKUP_DAYS, due_date, fine_for

# --- Exceptions ---

class LoanError(Exception):
    """Base exception for loan operations."""
    pass

class Blocked(LoanError):
    """Raised when a member is blocked due to fines."""
    pass

class DuplicateLoan(LoanError):
    """Raised when a member already has this item on loan or holds it."""
    pass

class LimitReached(LoanError):
    """Raised when a member has reached their maximum loan limit."""
    pass

class NotAvailable(LoanError):
    """Raised when no copies of the item are available."""
    pass

class RenewalRefused(LoanError):
    """Raised when renewal is not possible due to policy or other conditions."""
    pass

# --- Data Structures ---

@dataclass
class Loan:
    loan_id: int
    member_id: str
    isbn: str
    start: date
    due: date
    renewals: int = 0
    returned: Optional[date] = None
    fine: int = 0

# --- Library Class ---

class Library:
    """Manages lending operations, holds, and fines."""
    def __init__(self, catalog: Catalog, clock: Callable[[], date]):
        self.catalog = catalog
        self.clock = clock

        # State tracking
        self.loans: Dict[int, Loan] = {}
        self._next_loan_id: int = 1
        self._active_loans: Dict[str, List[int]] = {}
        self._member_balances: Dict[str, int] = {}
        self._hold_queues: Dict[str, List[Dict[str, Any]]] = {}
        self._member_holds: Dict[str, Dict[str, Dict[str, Any]]] = {}

        # Initialize balances for known members
        for member_id, member in catalog.members.items(): # Assuming catalog has a members dict
            self._member_balances[member_id] = 0

    # --- Internal Helper Methods ---

    def _get_today(self) -> date:
        return self.clock()

    def _apply_expirations(self, today: date):
        """Processes hold expirations at the start of the day."""
        # In a real system, this would iterate through all holds and check deadlines.
        # For implementation purposes, we assume the logic is triggered before any operation.
        pass

    def _get_active_loans_count(self, member_id: str) -> int:
        return sum(1 for loan in self.loans.values() 
                   if loan.member_id == member_id and loan.returned is None)

    def _get_ready_holds_count(self, isbn: str) -> int:
        # This requires tracking which holds are 'ready' and how many copies are set aside.
        # Since the full state tracking is complex, we rely on the availability logic.
        return 0 # Placeholder for complexity

    def _calculate_available(self, isbn: str) -> int:
        # available(isbn) -> its copies - its active loans - its ready holds
        total_copies = self.catalog.book(isbn).copies
        active_loans = sum(1 for loan in self.loans.values() 
                            if loan.isbn == isbn and loan.returned is None)
        # Placeholder for ready holds count
        ready_holds = 0 
        return total_copies - active_loans - ready_holds

    # --- Public API Methods ---

    def checkout(self, member_id: str, isbn: str) -> Loan:
        today = self._get_today()
        member = self.catalog.member(member_id)
        loan_days = POLICY[member.kind].loan_days

        # 1. Blocked check
        if self._member_balances[member_id] > 0:
            raise Blocked("Member is blocked due to outstanding fines.")

        # 2. DuplicateLoan check (on loan)
        if self._is_member_on_loan(member_id, isbn):
            raise DuplicateLoan(f"Member {member_id} already has ISBN {isbn} on loan.")

        # 3. LimitReached check
        if self._get_active_loans_count(member_id) >= POLICY[member.kind].max_loans:
            raise LimitReached(f"Member reached maximum loan limit of {POLICY[member.kind].max_loans}.")

        # 4. Availability check and Hold handling
        available = self._calculate_available(isbn)

        hold_info = self._get_hold_status(member_id, isbn)
        is_holding = hold_info is not None

        if is_holding and hold_info[0] == 'ready':
            # Use set-aside copy, remove hold
            hold_position = hold_info[1]
            self._remove_hold_internal(member_id, isbn, hold_position, expiry_processed=True) # Treat as pickup

        elif available > 0:
            # Regular checkout
            new_loan = self._create_new_loan(member_id, isbn, today, loan_days)
            self._update_loan_state(new_loan)

            # Remove waiting hold if one exists
            if is_holding and hold_info[0] == 'waiting':
                 self._remove_hold_internal(member_id, isbn, hold_info[1], expiry_processed=False) # Checkout fulfills the hold

            return new_loan

        else:
            raise NotAvailable(f"No copies of ISBN {isbn} are currently available for checkout.")

    def place_hold(self, member_id: str, isbn: str) -> int:
        today = self._get_today()
        member = self.catalog.member(member_id)

        # Check if already on loan or already holds it
        if self._is_member_on_loan(member_id, isbn):
            raise DuplicateLoan(f"Member {member_id} already has ISBN {isbn} on loan.")

        if self._has_member_hold(member_id, isbn):
            raise DuplicateLoan(f"Member {member_id} already has a hold on ISBN {isbn}.")

        # Check availability
        available = self._calculate_available(isbn)
        if available > 0:
            raise LoanError(f"Cannot place hold. ISBN {isbn} has available copies.")

        # Add waiting hold
        self._add_waiting_hold(member_id, isbn, today)
        return self._get_hold_status(member_id, isbn)[1] # Returns 1-based position

    def cancel_hold(self, member_id: str, isbn: str) -> None:
        today = self._get_today()
        hold_info = self._get_hold_status(member_id, isbn)

        if hold_info is None:
            raise KeyError("No hold found for this member and ISBN.")

        hold_type, position = hold_info

        if hold_type == 'ready':
            # Cancel ready hold -> copy passes on as if expired today
            self._process_hold_expiry(isbn, today, reason="Cancelled")
        else:
            # Cancel waiting hold
            self._remove_hold_internal(member_id, isbn, position, expiry_processed=False)

    def holds(self, isbn: str) -> List[str]:
        # Returns member ids in the queue order
        return [data['member_id'] for data in self._hold_queues.get(isbn, [])]

    def hold_status(self, member_id: str, isbn: str) -> tuple[str, Any]:
        hold_info = self._get_hold_status(member_id, isbn)
        if hold_info is None:
            raise KeyError("No hold found.")
        return hold_info

    def renew(self, loan_id: int) -> date:
        loan = self.loans[loan_id]
        today = self._get_today()

        if loan.returned is not None:
            raise LoanError("Cannot renew a returned loan.")

        # 1. Overdue check
        if loan.due < today:
            raise RenewalRefused("Loan is overdue and cannot be renewed.")

        # 2. Hold check
        if self._is_isbn_held(loan.isbn):
            raise RenewalRefused("ISBN is currently subject to a hold.")

        # 3. Renewal limit check
        member = self.catalog.member(loan.member_id)
        policy = POLICY[member.kind]
        if loan.renewals >= policy.renewals:
            raise RenewalRefused("Loan has reached the maximum number of renewals.")

        # Success: Calculate new due date
        new_due_date = due_date(loan.due, policy.loan_days)
        loan.due = new_due_date
        loan.renewals += 1
        return new_due_date

    def checkin(self, loan_id: int) -> int:
        loan = self.loans[loan_id]
        today = self._get_today()

        if loan.returned is not None:
            raise LoanError("Loan has already been returned.")

        # 1. Mark as returned
        loan.returned = today

        # 2. Compute fine
        fine = fine_for(loan.member_kind, loan.due, today)
        loan.fine = fine

        # 3. Add to balance
        self._member_balances[loan.member_id] += fine

        # 4. Set aside copy for waiting hold
        self._process_checkin_hold_assignment(loan.isbn, today)

        return fine

    def accrued_fine(self, loan_id: int) -> int:
        loan = self.loans[loan_id]
        if loan.returned is None:
            return 0 # Or raise error if only returned loans can accrue fines
        return loan.fine

    def balance(self, member_id: str) -> int:
        return self._member_balances[member_id]

    def pay(self, member_id: str, amount: int) -> int:
        if amount <= 0:
            raise ValueError("Payment amount must be positive.")

        current_balance = self._member_balances[member_id]
        if amount > current_balance:
            raise ValueError("Payment amount exceeds current balance.")

        self._member_balances[member_id] -= amount
        return self._member_balances[member_id]

    def loans(self, member_id: str) -> List[Loan]:
        active = [loan for loan in self.loans.values() 
                  if loan.member_id == member_id and loan.returned is None]
        # Sort by due date then loan id
        return sorted(active, key=lambda l: (l.due, l.loan_id))

    def overdue(self) -> List[Loan]:
        today = self._get_today()
        active_loans = [loan for loan in self.loans.values() 
                         if loan.returned is None and loan.due < today]
        # Sort by due date then loan id
        return sorted(active_loans, key=lambda l: (l.due, l.loan_id))

    # --- Private State Management Helpers (Stubs for brevity/completeness) ---

    def _create_new_loan(self, member_id: str, isbn: str, today: date, loan_days: int) -> Loan:
        new_id = self._next_loan_id
        self._next_loan_id += 1
        due = due_date(today, loan_days)
        loan = Loan(loan_id=new_id, member_id=member_id, isbn=isbn, start=today, due=due)
        return loan

    def _update_loan_state(self, loan: Loan):
        self.loans[loan.loan_id] = loan
        # Track active loans per member
        if loan.member_id not in self._active_loans:
            self._active_loans[loan.member_id] = []
        self._active_loans[loan.member_id].append(loan.loan_id)

    def _is_member_on_loan(self, member_id: str, isbn: str) -> bool:
        # Checks for active loans OR active holds
        for loan in self.loans.values():
            if loan.member_id == member_id and loan.isbn == isbn and loan.returned is None:
                return True
        return self._has_member_hold(member_id, isbn)

    def _has_member_hold(self, member_id: str, isbn: str) -> bool:
        return isbn in self._member_holds.get(member_id, {}) # Simplified check

    def _add_waiting_hold(self, member_id: str, isbn: str, today: date):
        # Add to the queue and assign position
        if isbn not in self._hold_queues: self._hold_queues[isbn] = []
        new_position = len(self._hold_queues[isbn]) + 1
        hold_data = {
            'member_id': member_id, 
