            'placed_date': today, 
            'ready_deadline': None # Waiting holds have no deadline
        }
        self._hold_queues[isbn].append(hold_data)

        # Update member holds tracker
        if member_id not in self._member_holds: self._member_holds[member_id] = {}
        self._member_holds[member_id][isbn] = {'type': 'waiting', 'position': new_position}

    def _get_hold_status(self, member_id: str, isbn: str) -> Optional[tuple[str, Any]]:
        # Determines if a hold is waiting or ready
        member_holds = self._member_holds.get(member_id, {}).get(isbn)
