from library.catalog import Catalog
from library.fines import POLICY, Policy, HOLD_PICKUP_DAYS, due_date, fine_for

# --- Exceptions ---

class LoanError(Exception):
    """Base exception for loan operations."""
    pass

class Blocked(LoanError):
    """Raised when a member is blocked due to fines."""
    pass

class DuplicateLoan(LoanError):
    """Raised when a member already has this item on loan or holds it."""
    pass

class LimitReached(LoanError):
    """Raised when a member has reached their maximum loan limit."""
    pass

class NotAvailable(LoanError):
    """Raised when no copies of the item are available."""
    pass

class RenewalRefused(LoanError):
    """Raised when renewal is not possible due to policy or other conditions."""
    pass

# --- Data Structures ---

@dataclass
class Loan:
    loan_id: int
    member_id: str
    isbn: str
    start: date
    due: date
    renewals: int = 0
    returned: Optional[date] = None
    fine: int = 0

