        today = self._get_today()
        hold_info = self._get_hold_status(member_id, isbn)

        if hold_info is None:
            raise KeyError("No hold found for this member and ISBN.")

        hold_type, position = hold_info

        if hold_type == 'ready':
            # Cancel ready hold -> copy passes on as if expired today
            self._process_hold_expiry(isbn, today, reason="Cancelled")
        else:
            # Cancel waiting hold
            self._remove_hold_internal(member_id, isbn, position, expiry_processed=False)

    def holds(self, isbn: str) -> List[str]:
        # Returns member ids in the queue order
        return [data['member_id'] for data in self._hold_queues.get(isbn, [])]

    def hold_status(self, member_id: str, isbn: str) -> tuple[str, Any]:
        hold_info = self._get_hold_status(member_id, isbn)
        if hold_info is None:
            raise KeyError("No hold found.")
        return hold_info

    def renew(self, loan_id: int) -> date:
        loan = self.loans[loan_id]
        today = self._get_today()

        if loan.returned is not None:
            raise LoanError("Cannot renew a returned loan.")

        # 1. Overdue check
        if loan.due < today:
            raise RenewalRefused("Loan is overdue and cannot be renewed.")

        # 2. Hold check
        if self._is_isbn_held(loan.isbn):
            raise RenewalRefused("ISBN is currently subject to a hold.")

        # 3. Renewal limit check
        member = self.catalog.member(loan.member_id)
        policy = POLICY[member.kind]
        if loan.renewals >= policy.renewals:
            raise RenewalRefused("Loan has reached the maximum number of renewals.")

        # Success: Calculate new due date
        new_due_date = due_date(loan.due, policy.loan_days)
        loan.due = new_due_date
        loan.renewals += 1
        return new_due_date

    def checkin(self, loan_id: int) -> int:
        loan = self.loans[loan_id]
        today = self._get_today()

        if loan.returned is not None:
            raise LoanError("Loan has already been returned.")

        # 1. Mark as returned
        loan.returned = today

        # 2. Compute fine
        fine = fine_for(loan.member_kind, loan.due, today)
        loan.fine = fine

        # 3. Add to balance
        self._member_balances[loan.member_id] += fine

        # 4. Set aside copy for waiting hold
        self._process_checkin_hold_assignment(loan.isbn, today)

        return fine

    def accrued_fine(self, loan_id: int) -> int:
        loan = self.loans[loan_id]
        if loan.returned is None:
            return 0 # Or raise error if only returned loans can accrue fines
        return loan.fine

    def balance(self, member_id: str) -> int:
        return self._member_balances[member_id]

    def pay(self, member_id: str, amount: int) -> int:
        if amount <= 0:
            raise ValueError("Payment amount must be positive.")

        current_balance = self._member_balances[member_id]
        if amount > current_balance:
            raise ValueError("Payment amount exceeds current balance.")

        self._member_balances[member_id] -= amount
        return self._member_balances[member_id]

    def loans(self, member_id: str) -> List[Loan]:
        active = [loan for loan in self.loans.values() 
                  if loan.member_id == member_id and loan.returned is None]
        # Sort by due date then loan id
        return sorted(active, key=lambda l: (l.due, l.loan_id))

    def overdue(self) -> List[Loan]:
        today = self._get_today()
        active_loans = [loan for loan in self.loans.values() 
                         if loan.returned is None and loan.due < today]
        # Sort by due date then loan id
        return sorted(active_loans, key=lambda l: (l.due, l.loan_id))

    # --- Private State Management Helpers (Stubs for brevity/completeness) ---

    def _create_new_loan(self, member_id: str, isbn: str, today: date, loan_days: int) -> Loan:
        new_id = self._next_loan_id
