        due = due_date(today, loan_days)
        loan = Loan(loan_id=new_id, member_id=member_id, isbn=isbn, start=today, due=due)
        return loan

    def _update_loan_state(self, loan: Loan):
        self.loans[loan.loan_id] = loan
        # Track active loans per member
        if loan.member_id not in self._active_loans:
            self._active_loans[loan.member_id] = []
        self._active_loans[loan.member_id].append(loan.loan_id)

    def _is_member_on_loan(self, member_id: str, isbn: str) -> bool:
        # Checks for active loans OR active holds
        for loan in self.loans.values():
            if loan.member_id == member_id and loan.isbn == isbn and loan.returned is None:
                return True
