    def _has_member_hold(self, member_id: str, isbn: str) -> bool:
        return isbn in self._member_holds.get(member_id, {}) # Simplified check

    def _add_waiting_hold(self, member_id: str, isbn: str, today: date):
        # Add to the queue and assign position
        if isbn not in self._hold_queues: self._hold_queues[isbn] = []
        new_position = len(self._hold_queues[isbn]) + 1
        hold_data = {
            'member_id': member_id, 
