from dataclasses import dataclass
from datetime import date
from typing import Dict

@dataclass(frozen=True)
class Policy:
    max_loans: int
    loan_days: int
    renewals: int
    daily_fine: int
    fine_cap: int
    grace_days: int

# Policy table keyed by member kind
POLICY: Dict[str, Policy] = {
    "standard": Policy(max_loans=5, loan_days=21, renewals=2, daily_fine=25, fine_cap=1000, grace_days=0),
    "student": Policy(max_loans=3, loan_days=14, renewals=1, daily_fine=10, fine_cap=500, grace_days=2),
    "staff": Policy(max_loans=10, loan_days=42, renewals=3, daily_fine=0, fine_cap=0, grace_days=0),
}

HOLD_PICKUP_DAYS = 3

def due_date(start: date, days: int) -> date:
    """Calculates the due date, moving it to the following Monday if it falls on a Sunday."""
    # Simple addition first
    new_date = start.replace(day=1) + date(2000, 1, 1).replace(day=days + 1) - date(2000, 1, 1).replace(day=1)

    # Check if it's a Sunday (weekday() returns 6 for Sunday)
    if new_date.weekday() == 6:
        # Move to Monday (add 1 day)
        return new_date.replace(day=new_date.day + 1)
    return new_date

def fine_for(kind: str, due: date, returned: date) -> int:
    """Calculates the fine for a loan."""
    if kind not in POLICY:
        raise KeyError(f"Unknown member kind: {kind}")

    policy = POLICY[kind]

    late = (returned - due).days

    if late <= policy.grace_days:
        return 0

    # Fine accrues starting from the day *after* the grace period ends
    # The prompt says: "Once past the grace period every late day counts, including the grace days."
    # This phrasing is slightly ambiguous. If grace_days=2, and returned is 3 days late (late=3),
    # does the fine start accruing on day 1 (total 3 days late) or on day 3 (total 3 days late)?
    # The rule: "the fine is 0 if late <= grace_days"
    # If late = 3 and grace_days = 2, fine > 0.
    # The next part: "Once past the grace period every late day counts, including the grace days."
    # Interpretation: If late=3, and grace=2, the number of chargeable days is 3.

    chargeable_days = late

    fine_amount = chargeable_days * policy.daily_fine

    return min(fine_amount, policy.fine_cap)
