from dataclasses import dataclass, field
from datetime import date, timedelta
from typing import Optional, List, Callable, Dict, Any

# Import necessary components from other modules
from .catalog import Catalog, Book, Member
from .fines import POLICY, Policy, HOLD_PICKUP_DAYS, fine_for

# --- Exceptions ---
class LoanError(Exception):
    """Base exception for loan system."""
    pass

class Blocked(LoanError):
    """Raised when a member has outstanding fines."""
    pass

class DuplicateLoan(LoanError):
    """Raised when the member already has this ISBN on loan."""
    pass

class LimitReached(LoanError):
    """Raised when the member has reached their loan limit."""
    pass

class NotAvailable(LoanError):
    """Raised when no copies of the book are available."""
    pass

class RenewalRefused(LoanError):
    """Raised when loan renewal is not permitted by policy or status."""
    pass

# --- Data Structures ---
@dataclass
class Loan:
    loan_id: int
    member_id: str
    isbn: str
    start: date
    due: date
    renewals: int = 0
    returned: Optional[date] = None
    fine: int = 0

class Library:
    """The core library system managing catalog and loans."""
    def __init__(self, catalog: Catalog, clock: Callable[[], date]):
        self.catalog = catalog
        self.clock = clock
        self._loans: Dict[int, Loan] = {}
        self._loan_counter: int = 0
        self._member_balances: Dict[str, int] = {member.member_id: 0 for member in catalog.members.values()}

        # Hold management: {isbn: List[str]} -> List of member_ids waiting for this book
        self._waiting_holds: Dict[str, List[str]] = {}

        # Ready holds: {isbn: List[tuple[str, date]]} -> List of (member_id, deadline) ready to be picked up
        # Sorted by deadline
        self._ready_holds: Dict[str, List[tuple[str, date]]] = {}

        # Tracking active loans by ISBN to check for duplicate loans
        self._active_loans_by_isbn: Dict[str, List[int]] = {}

    def _get_today(self) -> date:
        return self.clock()

    def _get_loan_next_id(self) -> int:
        self._loan_counter += 1
        return self._loan_counter

    def _apply_daily_expiry(self, today: date):
        """Applies hold expirations at the start of the day."""
        for isbn, ready_holds in list(self._ready_holds.items()):
            if isbn not in self._waiting_holds:
                continue

            # Identify holds that expired yesterday or earlier (deadline < today)
            expired_holds = [(
                mid, deadline
            ) for mid, deadline in ready_holds if deadline < today]

            if not expired_holds:
                continue

            # Process expired holds in order of expiry
            ready_holds[:] = [rh for rh in ready_holds if rh not in expired_holds]

            for _, _ in expired_holds:
                # Find the next waiting hold
                waiting_ids = self._waiting_holds.get(isbn, [])
                if waiting_ids:
                    next_holder_id = waiting_ids.pop(0)
                    # The copy becomes ready for the next holder, deadline is today + HOLD_PICKUP_DAYS
                    new_deadline = today + timedelta(days=HOLD_PICKUP_DAYS)

                    if isbn not in self._ready_holds:
                        self._ready_holds[isbn] = []
                    self._ready_holds[isbn].append((next_holder_id, new_deadline))

                    # Keep ready holds sorted by deadline
                    self._ready_holds[isbn].sort(key=lambda x: x[1])
                else:
                    # No waiting holds, copy becomes available
                    pass

    def available(self, isbn: str) -> int:
        """Returns the number of available copies."""
        total_copies = self.catalog.book(isbn).copies

        active_loans = len(self._active_loans_by_isbn.get(isbn, []))

        # Ready holds count as if they are set aside
        ready_holds_count = len(self._ready_holds.get(isbn, []))

        return total_copies - active_loans - ready_holds_count

    def checkout(self, member_id: str, isbn: str) -> Loan:
        today = self._get_today()

        # 0. Pre-check: Ensure member/book exist
        try:
            member = self.catalog.member(member_id)
        except KeyError:
            raise KeyError(f"Member ID {member_id} not found.")

        try:
            book = self.catalog.book(isbn)
        except KeyError:
            raise KeyError(f"ISBN {isbn} not found in catalog.")

        # 1. Check Blocked status
        if self._member_balances[member_id] > 0:
            raise Blocked()

        # 2. Check DuplicateLoan
        if isbn in [l.isbn for l in self.loans(member_id) if l.returned is None]:
            raise DuplicateLoan()

        # 3. Check LimitReached
        active_count = len([l for l in self.loans(member_id) if l.returned is None])
        policy = POLICY[member.kind]
        if active_count >= policy.max_loans:
            raise LimitReached()

        # 4. Determine copy source & manage holds
        is_ready_hold = isbn in self._ready_holds and any(mid == member_id for mid, _ in self._ready_holds[isbn])

        if is_ready_hold:
            # Use the set-aside copy for the ready hold and remove the hold
            self._ready_holds[isbn] = [(mid, deadline) for mid, deadline in self._ready_holds[isbn] if mid != member_id]
            # The hold is removed, so we don't need to update waiting holds.
        elif self.available(isbn) <= 0:
            raise NotAvailable()
        else:
            # No ready hold, just an available copy
            pass

        # Remove waiting hold if one existed
        if isbn in self._waiting_holds and member_id in self._waiting_holds[isbn]:
            self._waiting_holds[isbn].remove(member_id)

        # Create Loan
        loan_id = self._get_loan_next_id()
        loan_days = POLICY[member.kind].loan_days
        due_date_val = self.catalog.due_date(today, loan_days)

        new_loan = Loan(
            loan_id=loan_id,
            member_id=member_id,
            isbn=isbn,
            start=today,
            due=due_date_val,
            renewals=0,
            returned=None,
            fine=0
        )

        # Update state
        self._loans[loan_id] = new_loan
        if isbn not in self._active_loans_by_isbn: self._active_loans_by_isbn[isbn] = []
        self._active_loans_by_isbn[isbn].append(loan_id)

        return new_loan

    def place_hold(self, member_id: str, isbn: str) -> int:
        today = self._get_today()

        # 0. Pre-check: Ensure member/book exist
        try:
            member = self.catalog.member(member_id)
        except KeyError:
            raise KeyError(f"Member ID {member_id} not found.")

        try:
            book = self.catalog.book(isbn)
        except KeyError:
            raise KeyError(f"ISBN {isbn} not found in catalog.")

        # Check if currently on loan or already holding
        if isbn in [l.isbn for l in self.loans(member_id) if l.returned is None]:
            raise DuplicateLoan()

        # Check if already has a hold
        if isbn in self._waiting_holds and member_id in self._waiting_holds[isbn]:
            # This case should theoretically be covered by the check above if they are actively waiting
            # but if they have a ready hold, it's also a conflict.
            if isbn in self._ready_holds and any(mid == member_id for mid, _ in self._ready_holds[isbn]):
                 raise DuplicateLoan()
            # If they are already in the waiting list, we assume they are fine or raise error as per spec
            # Spec says: "DuplicateLoan if the member already has the isbn on loan or already has a hold on it"
            raise DuplicateLoan()

        # Check availability
        if self.available(isbn) > 0:
            raise LoanError("Cannot place a hold when copies are available.")

        # Add waiting hold
        if isbn not in self._waiting_holds:
            self._waiting_holds[isbn] = []

        self._waiting_holds[isbn].append(member_id)
        position = len(self._waiting_holds[isbn])
        return position

    def cancel_hold(self, member_id: str, isbn: str) -> None:
        today = self._get_today()

        # 1. Cancel waiting hold
        if isbn in self._waiting_holds and member_id in self._waiting_holds[isbn]:
            self._waiting_holds[isbn].remove(member_id)
            return

        # 2. Cancel ready hold
        if isbn in self._ready_holds:
            original_count = len(self._ready_holds[isbn])
            self._ready_holds[isbn] = [(
                mid, deadline
            ) for mid, deadline in self._ready_holds[isbn] if mid != member_id]

            if len(self._ready_holds[isbn]) < original_count:
                # Successfully cancelled a ready hold. Pass the copy on.
                self._process_hold_expiry_simulated(isbn, today)
                return

        # If neither was found
        raise KeyError(f"No active hold found for member {member_id} on ISBN {isbn}.")

    def _process_hold_expiry_simulated(self, isbn: str, today: date):
        """Internal helper to process expiry, used by cancel_hold or automatic expiry."""
        waiting_ids = self._waiting_holds.get(isbn, [])
        if not waiting_ids:
            return

        next_holder_id = waiting_ids.pop(0)
        new_deadline = today + timedelta(days=HOLD_PICKUP_DAYS)

        if isbn not in self._ready_holds:
            self._ready_holds[isbn] = []

        self._ready_holds[isbn].append((next_holder_id, new_deadline))
        self._ready_holds[isbn].sort(key=lambda x: x[1])

    def holds(self, isbn: str) -> List[str]:
        """Returns the member ids in the waiting hold queue, in order."""
        return self._waiting_holds.get(isbn, []).copy()

    def hold_status(self, member_id: str, isbn: str) -> tuple[str, Any]:
        today = self._get_today()

        # Check ready holds
        if isbn in self._ready_holds:
            for mid, deadline in self._ready_holds[isbn]:
                if mid == member_id:
                    return ('ready', deadline)

        # Check waiting holds
        if isbn in self._waiting_holds:
            try:
                position = self._waiting_holds[isbn].index(member_id) + 1
                return ('waiting', position)
            except ValueError:
                pass # Should not happen if logic is sound

        raise KeyError(f"No hold found for member {member_id} on ISBN {isbn}.")

    def renew(self, loan_id: int) -> date:
        today = self._get_today()

        if loan_id not in self._loans:
            raise KeyError(f"Loan ID {loan_id} not found.")

        loan = self._loans[loan_id]
        if loan.returned is not None:
            raise LoanError("Loan has already been returned.")

        policy = POLICY[self.catalog.member(loan.member_id).kind]

        # 1. Check if overdue
        if loan.due >= today:
            # It's not overdue, renewal is fine unless other restrictions apply
            pass

        # 2. Check if ISBN has any hold (waiting or ready)
        if isbn in self._waiting_holds or (isbn in self._ready_holds and self._ready_holds[isbn]):
            raise RenewalRefused()

        # 3. Check renewal limit
        if loan.renewals >= policy.renewals:
            raise RenewalRefused()

        # Perform renewal
        new_due_date = self.catalog.due_date(loan.due, policy.loan_days)

        loan.due = new_due_date
        loan.renewals += 1

        return new_due_date

    def checkin(self, loan_id: int) -> int:
        today = self._get_today()

        if loan_id not in self._loans:
            raise KeyError(f"Loan ID {loan_id} not found.")

        loan = self._loans[loan_id]
        if loan.returned is not None:
            raise LoanError("Loan already returned.")

        member = self.catalog.member(loan.member_id)
        isbn = loan.isbn

        # 1. Mark loan as returned
        loan.returned = today

        # 2. Compute fine
        fine_charged = fine_for(member.kind, loan.due, today)
        loan.fine = fine_charged

        # 3. Update member balance
        self._member_balances[loan.member_id] += fine_charged

        # 4. Update active loan tracking
        if isbn in self._active_loans_by_isbn:
            self._active_loans_by_isbn[isbn].remove(loan_id)
            if not self._active_loans_by_isbn[isbn]:
                del self._active_loans_by_isbn[isbn]

        # 5. Set aside copy for waiting hold
        if isbn in self._waiting_holds and self._waiting_holds[isbn]:
            self._process_hold_expiry_simulated(isbn, today)

        return fine_charged

    def accrued_fine(self, loan_id: int) -> int:
        if loan_id not in self._loans:
            raise KeyError(f"Loan ID {loan_id} not found.")
        loan = self._loans[loan_id]
        if loan.returned is None:
            # If not returned, compute fine as if returned today
            member = self.catalog.member(loan.member_id)
            return fine_for(member.kind, loan.due, self._get_today())
        return loan.fine

    def balance(self, member_id: str) -> int:
        return self._member_balances.get(member_id, 0)

    def pay(self, member_id: str, amount: int) -> int:
        current_balance = self.balance(member_id)
        if amount <= 0:
            raise ValueError("Payment amount must be positive.")
        if amount > current_balance:
            raise ValueError("Payment amount exceeds balance.")

        self._member_balances[member_id] -= amount
        return self._member_balances[member_id]

    def loans(self, member_id: str) -> List[Loan]:
        active_loans = [l for l in self._loans.values() if l.member_id == member_id and l.returned is None]
        # Sorted by due date, then loan id
        return sorted(active_loans, key=lambda l: (l.due, l.loan_id))

