import re
from typing import Any, Dict, List, Set, Tuple, Callable, Union

# --- Custom Types and Exceptions ---

class FormulaError(ValueError):
    """Raised for syntax or structural errors in a formula."""
    pass

class ErrorValue(str):
    """Represents a calculated error value. Inherits from str to compare equal to text."""
    def __init__(self, value: str):
        super().__init__(value)
        self.value = value

    def __str__(self) -> str:
        return self.value

    def __eq__(self, other: object) -> bool:
        if isinstance(other, ErrorValue): 
            return self.value == other.value
        return super().__eq__(other)

# Type hints for values
CellValue = Union[int, float, str, None, ErrorValue]

# --- Syntax Tree Nodes ---

class ASTNode:
    """Base class for all nodes in the Abstract Syntax Tree."""
    pass

class NumberLiteral(ASTNode):
    def __init__(self, value: Union[int, float]):
        self.value = value

    def __repr__(self) -> str:
        return f"NumberLiteral({self.value})"

class Reference(ASTNode):
    def __init__(self, name: str):
        self.name = name.upper()

    def __repr__(self) -> str:
        return f"Reference('{self.name}')"

class BinaryOperation(ASTNode):
    def __init__(self, op: str, left: ASTNode, right: ASTNode):
        self.op = op  # '+', '-', '*', '/'
        self.left = left
        self.right = right

    def __repr__(self) -> str:
        return f"BinOp('{self.op}', {self.left}, {self.right})"

class UnaryOperation(ASTNode):
    def __init__(self, op: str, operand: ASTNode):
        self.op = op  # '+', '-'
        self.operand = operand

    def __repr__(self) -> str:
        return f"UnOp('{self.op}', {self.operand})"

class ParenExpression(ASTNode):
    def __init__(self, expr: ASTNode):
        self.expr = expr

    def __repr__(self) -> str:
        return f"ParenExpression({self.expr})"

# --- Lexer/Tokenizer ---

# Regex patterns for tokens. Whitespace is handled by skipping.
TOKEN_SPECIFICATION = [ 
    ('NUMBER', r'[0-9]+(\.[0-9]+)?'),
    ('REF', r'[a-zA-Z]+[0-9]+'), # Letters followed by digits (e.g., A1, B10)
    ('LPAREN', r'\('),
    ('RPAREN', r'\)'),
    ('PLUS', r'\+'),
    ('MINUS', r'\-'),
    ('MUL', r'\*'),
    ('DIV', r'\/'),
    ('SKIP', r'[ \t\n]+'), # Whitespace
    ('MISMATCH', r'.'),     # Any other character
]

TOKEN_REGEX = '|'.join('(?P<%s>%s)' % pair for pair in TOKEN_SPECIFICATION)

class Token:
    def __init__(self, type: str, value: str):
        self.type = type
        self.value = value

    def __repr__(self) -> str:
        return f"Token({self.type}, {repr(self.value)})"

class Lexer:
    def __init__(self, source: str):
        self.source = source
        self.tokens: List[Token] = []
        self._tokenize()

    def _tokenize(self):
        for mo in re.finditer(TOKEN_REGEX, self.source):
            kind = mo.lastgroup
            value = mo.group()

            if kind == 'SKIP':
                continue
            elif kind == 'MISMATCH':
                raise FormulaError(f"Illegal character: {value}")
            else:
                self.tokens.append(Token(kind, value))

    def get_tokens(self) -> List[Token]:
        return self.tokens

# --- Parser (Recursive Descent) ---

class Parser:
    def __init__(self, tokens: List[Token]):
        self.tokens = tokens
        self.pos = 0

    def current_token(self) -> Token | None:
        return self.tokens[self.pos] if self.pos < len(self.tokens) else None

    def advance(self) -> Token | None:
        if self.pos < len(self.tokens):
            token = self.tokens[self.pos]
            self.pos += 1
            return token
        return None

    def eat(self, expected_type: str): 
        token = self.current_token()
        if token and token.type == expected_type:
            self.advance()
        else:
            raise FormulaError(f"Expected {expected_type}, got {token.type if token else 'EOF'}")

    def parse(self) -> ASTNode:
        # Grammar: expr := term {(+ | -) term}
        node = self._parse_expr()

        if self.current_token() is not None:
            raise FormulaError("Unexpected tokens remaining after parsing.")
        return node

    # Level 1: Addition and Subtraction (Lowest Precedence)
    def _parse_expr(self) -> ASTNode:
        node = self._parse_term()

        while self.current_token() and self.current_token().type in ('PLUS', 'MINUS'):
            op_token = self.advance()
            right = self._parse_term()
            node = BinaryOperation(op_token.type, node, right)
        return node

    # Level 2: Multiplication and Division (Medium Precedence)
    def _parse_term(self) -> ASTNode:
        node = self._parse_unary()

        while self.current_token() and self.current_token().type in ('MUL', 'DIV'):
            op_token = self.advance()
            right = self._parse_unary()
            node = BinaryOperation(op_token.type, node, right)
        return node

    # Level 3: Unary Operators, Numbers, Refs, Parentheses (Highest Precedence)
    def _parse_unary(self) -> ASTNode:
        token = self.current_token()

        # Check for unary +/-
        if token and token.type == 'PLUS':
            self.advance() # Consume '+'
            return UnaryOperation('+', self._parse_unary())
        elif token and token.type == 'MINUS':
            self.advance() # Consume '-'
            return UnaryOperation('-', self._parse_unary())

        # Check for parentheses or base elements
        if token and token.type == 'LPAREN':
            self.advance() # Consume '('
            node = self._parse_expr()
            self.eat('RPAREN') # Consume ')'
            return ParenExpression(node)

        # Check for number or reference
        if token and token.type == 'NUMBER':
            self.advance()
            try:
                # Determine if it's int or float
                value_str = token.value
                if '.' in value_str:
                    return NumberLiteral(float(value_str))
                else:
                    return NumberLiteral(int(value_str))
            except ValueError:
                # Should not happen if regex is correct, but good practice
                raise FormulaError(f"Invalid number format: {token.value}")

        elif token and token.type == 'REF':
            self.advance()
            return Reference(token.value)

        else:
            raise FormulaError(f"Expected number, reference, or '(' but found {token.type if token else 'EOF'}")

# --- Public API Functions ---

def parse_formula(source: str) -> ASTNode:
    """Parses the text after '=' into a syntax tree."""
    if not source:
        raise FormulaError("Formula source cannot be empty.")

    try:
        lexer = Lexer(source)
        tokens = lexer.get_tokens()
        if not tokens: # Handles case where source is just whitespace
             raise FormulaError("Formula source resulted in no tokens.")

        parser = Parser(tokens)
        return parser.parse()
    except FormulaError as e:
        # Re-raise parsing errors
        raise e
    except Exception as e:
        # Catch unexpected errors during lexing/parsing
        raise FormulaError(f"Unexpected error during formula parsing: {e}")

def references(tree: ASTNode) -> Set[str]:
    """Returns the upper-case names of the cells the formula refers to."""
    found_refs: Set[str] = set()

    def traverse(node: ASTNode):
        if isinstance(node, Reference):
            found_refs.add(node.name)
        elif isinstance(node, BinaryOperation):
            traverse(node.left)
            traverse(node.right)
        elif isinstance(node, UnaryOperation):
            traverse(node.operand)
        elif isinstance(node, ParenExpression):
            traverse(node.expr)
        # NumberLiteral adds nothing

    traverse(tree)
    return found_refs

# --- Evaluation Logic ---

def _evaluate_node(node: ASTNode, lookup: Callable[[str], CellValue], cycle_cells: Set[str]) -> CellValue:
    """Recursively evaluates a single AST node."""

    # Rule 2: Cycle detection
    if isinstance(node, Reference) and node.name in cycle_cells:
        return ErrorValue("#CYCLE!")

    if isinstance(node, NumberLiteral):
        return node.value

    elif isinstance(node, Reference):
        name = node.name
        value = lookup(name)

        # Rule 2: Empty cell (None) gives 0
        if value is None:
            return 0

        # Rule 2: A formula that is only a reference returns text unchanged
        if isinstance(value, str) and not isinstance(value, ErrorValue):
            return value

        # Return the actual cell value (including ErrorValue if it's not None/str)
        return value

    elif isinstance(node, BinaryOperation):
        left_val = _evaluate_node(node.left, lookup, cycle_cells)
        right_val = _evaluate_node(node.right, lookup, cycle_cells)

        # Rule 3: Error propagation
        if isinstance(left_val, ErrorValue) or isinstance(right_val, ErrorValue):
            # Left one if both are errors
            return left_val if isinstance(left_val, ErrorValue) else right_val

        # Rule 3: Text evaluation
        if isinstance(left_val, str) and not isinstance(left_val, ErrorValue) or 
           isinstance(right_val, str) and not isinstance(right_val, ErrorValue):
            return ErrorValue("#ERROR!")

        # Rule 4: Arithmetic evaluation
        op = node.op

        if op == '+':
            # Integer/Float promotion
            if isinstance(left_val, int) and isinstance(right_val, int):
                return left_val + right_val
            if isinstance(left_val, float) or isinstance(right_val, float):
                return left_val + right_val
            # Should not happen if prior text/error checks are correct, but handles safety
            return ErrorValue("#ERROR!") 

        elif op == '-':
            # Integer/Float promotion
            if isinstance(left_val, int) and isinstance(right_val, int):
                return left_val - right_val
            if isinstance(left_val, float) or isinstance(right_val, float):
                return left_val - right_val
            return ErrorValue("#ERROR!")

        elif op == '*':
            # Integer/Float promotion
            if isinstance(left_val, int) and isinstance(right_val, int):
                return left_val * right_val
            if isinstance(left_val, float) or isinstance(right_val, float):
                return left_val * right_val
            return ErrorValue("#ERROR!")

        elif op == '/':
            # Rule 4: Division always gives float
            if right_val == 0:
                return ErrorValue("#ERROR!")
            if isinstance(left_val, int) and isinstance(right_val, int):
                return float(left_val) / right_val
            return float(left_val) / right_val

    elif isinstance(node, UnaryOperation):
        operand_val = _evaluate_node(node.operand, lookup, cycle_cells)

        if isinstance(operand_val, ErrorValue):
            return operand_val

        # Unary +/- only applies to numbers (or things that evaluate to numbers)
        if isinstance(operand_val, (int, float)):
            if node.op == '+':
                return operand_val
            else: # '-'
                return -operand_val
        else:
            # If the operand was text or something else, applying unary operator results in error
            return ErrorValue("#ERROR!")

    elif isinstance(node, ParenExpression):
        return _evaluate_node(node.expr, lookup, cycle_cells)

    else:
        # Should be unreachable if grammar is fully covered
        raise FormulaError(f"Unknown node type during evaluation: {type(node)}")

def evaluate(tree: ASTNode, lookup: Callable[[str], CellValue]) -> CellValue:
    """Computes the formula's value."""
    # NOTE: cycle_cells argument is not provided in the function signature, 
    # but based on usage context (Sheet), it needs to be passed externally or assumed.
    # For this isolated module implementation, we must assume the caller handles cycle checking 
    # or we must assume cycle_cells is empty if not provided by the Sheet class.
    # Since the spec implies this function is part of the evaluation pipeline where cycle info exists,
    # I will rely on the lookup function potentially handling this, but for pure formula evaluation
    # without graph context, I cannot properly implement cycle checking internally.
    # Based on the rules (Rule 2: A cell on a cycle has the value #CYCLE! ... A cell that refers to a #CYCLE! cell gets #CYCLE!), 
    # the evaluation *must* be aware of cycles. 

    # Given the constraints, I must assume 'lookup' handles the cycle detection if the cycle is present
    # in the input cell values, or I must assume no cycles for this pure function call.
    # Since the specification for evaluate only lists 'lookup', I will proceed without passing cycle_cells here,
    # relying on the context provided by the caller (Sheet) to ensure lookup returns #CYCLE! if needed.

    # However, to satisfy the internal logic I wrote above, I'll pass an empty set, which is technically incorrect 
    # without the graph context, but required for the function signature.
    return _evaluate_node(tree, lookup, set()) 
