from typing import Set, Iterable

class DependencyGraph:
    """Records, for each cell, the cells its formula refers to (its precedents)."""
    def __init__(self):
        # Maps cell name to set of cells it depends on (precedents)
        self._precedents: dict[str, Set[str]] = {}
        # Maps cell name to set of cells that depend on it (dependents)
        self._dependents: dict[str, Set[str]] = {}

    def set_dependencies(self, cell: str, precedents: Iterable[str]) -> None:
        """Replaces cell's precedents with the given iterable of names (empty removes them)."""
        precedent_set = set(precedents)
        self._precedents[cell] = precedent_set

        # 1. Update dependents relationships based on new precedents
        # Clear old dependent links for this cell
        self._dependents[cell] = set()

        # 2. Update the dependents of the *old* precedents (this is complex, but for simplicity and matching the API, we rebuild dependents based on current state)
        # Since this method is called when dependencies change, we need to iterate over all cells to ensure dependents are correct, or maintain the reverse graph.
        # A simpler approach for this method: update the graph structure based on the new dependency list.

        # Reset dependents for all affected cells (cell itself and its previous precedents)
        # Since we only have the new precedents, we must ensure all *new* precedents point to 'cell' as a dependent.

        # First, clear all incoming edges to 'cell' in the dependents map (this is not fully robust without knowing the old state, but we focus on the new state)
        for other_cell in list(self._dependents.keys()):
            if cell in self._dependents[other_cell]:
                self._dependents[other_cell].remove(cell)

        # Now, add 'cell' to the dependents of each new precedent
        for p in precedent_set:
            if p not in self._dependents: 
                self._dependents[p] = set()
            self._dependents[p].add(cell)

        # Ensure 'cell' itself is in _dependents even if it has no dependents yet
        if cell not in self._dependents: 
            self._dependents[cell] = set()

    def precedents(self, cell: str) -> Set[str]:
        """Returns the direct precedents of cell (an empty set for an unknown cell)."""
        return self._precedents.get(cell, set())

    def dependents(self, cell: str) -> Set[str]:
        """Returns the direct dependents of cell (an empty set for an unknown cell)."""
        return self._dependents.get(cell, set())

    def all_dependents(self, cell: str) -> Set[str]:
        """Returns every cell that refers to cell directly or through other cells. Contains cell itself only when cell is on a cycle."""
        if cell not in self._dependents: 
            return set()

        # BFS starting from cell using the _dependents map
        queue = [cell]
        visited = {cell}

        while queue:
            current = queue.pop(0)
            # Add current to the result set. Note: the rule states it contains cell itself only if on a cycle. 
            # A standard BFS on the dependent graph naturally finds all cells reachable from 'cell'. 
            # We will handle the cycle inclusion based on the cycle_cells method later, but for now, we traverse everything reachable.
            # To strictly adhere to the rule, we might need to check for cycles during traversal or rely on cycle_cells().
            # Since cycle_cells() determines cycle membership, we'll return all reachable nodes for now, as cycle detection is separate.

            for dependent in self._dependents.get(current, set()):
                if dependent not in visited:
                    visited.add(dependent)
                    queue.append(dependent)

        # Re-check the requirement: "It contains cell itself only when cell is on a cycle."
        # A simple traversal includes 'cell' itself as the starting point.
        # We must filter this result based on cycle_cells().
        cycle_set = self.cycle_cells()

        if cell in cycle_set:
             # If it's on a cycle, return all reachable nodes, including itself
             return visited
        else:
             # If it's not on a cycle, return all reachable nodes excluding itself
             return visited - {cell}

    def cycle_cells(self) -> Set[str]:
        """Gives every cell that lies on a cycle, that is, a cell from which following precedents leads back to itself."""
        # Use Tarjan's or Kosaraju's algorithm for SCCs. Since we only need cycle membership, a DFS-based approach tracking recursion stack is simpler.

        visiting: Set[str] = set()  # Nodes currently in the recursion stack
        visited: Set[str] = set()   # Nodes fully processed
        cycles: Set[str] = set()    # Nodes identified as being in a cycle

        # Ensure all known cells are checked
        all_cells = set(self._precedents.keys()) | set(self._dependents.keys())

        def dfs(u: str) -> bool: # Returns True if a cycle was found starting from u
            if u in visiting:
                # Cycle detected: u is currently in the recursion stack and we reached it again
                cycles.add(u)
                return True
            if u in visited:
                # Already fully processed, no need to re-explore
                return False

            visiting.add(u)

            # Check precedents
            pre = self._precedents.get(u, set())
            for v in pre:
                if dfs(v):
                    # If a cycle was found down this path, add u to the cycle set if it can reach that cycle node
                    # Since we are backtracking, if any precedent leads to a cycle, u is part of the path leading to it, 
                    # and if that path closes, u is part of the cycle.
                    # The detection logic above (u in visiting) handles the immediate cycle.
                    # For transitive cycles (A->B->C->A), when DFS hits A from C, it detects the cycle at A.
                    # We must ensure all nodes involved in the recursive path leading to the cycle are marked.
                    if v in cycles:
                        cycles.add(u)

            visiting.remove(u)
            visited.add(u)
            return u in cycles # Return True if u itself ended up in a cycle set

        for cell in all_cells:
            if cell not in visited:
                dfs(cell)

        return cycles
