```python
from typing import Any, Union, List, Set, Dict, Callable, Tuple
import re

# --- Custom Exceptions and Types ---

class FormulaError(ValueError):
    """Raised for syntax errors or out-of-bounds references during parsing."""
    pass

class ErrorValue(str):
    """Represents an error state in a cell's value."""
    pass

# Define the types of values a cell can hold
CellValue = Union[int, float, str, None, ErrorValue]

# --- AST Node Definitions ---

class ASTNode:
    """Base class for all nodes in the syntax tree."""
    pass

class NumberNode(ASTNode):
    """Represents a numeric literal."""
    def __init__(self, value: Union[int, float]):
        self.value = value

    def __repr__(self):
        return f"NumberNode({self.value})"

class RefNode(ASTNode):
    """Represents a cell reference (e.g., 'A1')."""
    def __init__(self, name: str): # name is expected to be uppercase
        self.name = name

    def __repr__(self):
        return f"RefNode('{self.name}')"

class UnaryOpNode(ASTNode):
    """Represents a unary operation (+ or -) applied to a single operand."""
    def __init__(self, op: str, operand: ASTNode):
        self.op = op  # '+' or '-'
        self.operand = operand

    def __repr__(self):
        return f"UnaryOpNode('{self.op}', {self.operand})"

class BinaryOpNode(ASTNode):
    """Represents a binary operation (*, /, +, or -) between two operands."""
    def __init__(self, op: str, left: ASTNode, right: ASTNode):
        self.op = op  # '+', '-', '*', or '/'
        self.left = left
        self.right = right

    def __repr__(self):
        return f"BinaryOpNode('{self.op}', {self.left}, {self.right})"

# --- Tokenizer / Lexer ---

TOKEN_SPEC = [  # Order matters for precedence in matching
    ('NUMBER', r'[0-9]+(\.[0-9]+)?'),  # Numbers (integers or floats)
    ('REF', r'[A-Z][0-9]+'),            # References (must match A-Z then digits, case-insensitive handled later)
    ('LPAREN', r'\('),                  # ( 
    ('RPAREN', r'\)'),                  # ) 
    ('PLUS', r'\+'),                    # + 
    ('MINUS', r'\-'),                    # - 
    ('MUL', r'\*'),                     # * 
    ('DIV', r'\/'),                     # / 
    ('SKIP', r'[ \t]+'),                # Whitespace to skip
    ('MISMATCH', r'.'),                  # Any other character
]

class Token:
    def __init__(self, type: str, value: str):
        self.type = type
        self.value = value

    def __repr__(self):
        return f'Token({self.type}, {self.value})'

class Lexer:
    def __init__(self, text: str):
        self.text = text
        self.tokens: List[Token] = []
        self._tokenize()

    def _tokenize(self):
        tokens = []
        pos = 0
        while pos < len(self.text):
            match = None
            for token_type, pattern in TOKEN_SPEC:
                regex = re.compile(f"^({pattern})")
                m = regex.match(self.text[pos:])
                if m:
                    value = m.group(1)
                    if token_type == 'SKIP':
                        pos += len(value)
                        break
                    elif token_type == 'MISMATCH':
                        raise FormulaError(f"Illegal character '{value[0]}' at position {pos}")

                    # Special handling for REF to handle case-insensitivity check later
                    if token_type == 'REF':
                        # We tokenize case-insensitively, but store the original for validation
                        tokens.append(Token('REF', value))
                    else:
                        tokens.append(Token(token_type, value))
                    pos += len(value)
                    break
            else:
                 # Should not happen if MISMATCH is last, but good safeguard
                 raise FormulaError(f"Lexer error at position {pos}")

        self.tokens = tokens

    def get_tokens(self) -> List[Token]:
        return self.tokens

# --- Parser (Recursive Descent) ---

class Parser:
    def __init__(self, tokens: List[Token]):
        self.tokens = tokens
        self.pos = 0

    def peek(self) -> Token | None:
        return self.tokens[self.pos] if self.pos < len(self.tokens) else None

    def consume(self, expected_type: str = None, expected_value: str = None) -> Token:
        token = self.peek()
        if not token:
            raise FormulaError("Unexpected end of expression.")

        if expected_type and token.type != expected_type:
            raise FormulaError(f"Expected token type {expected_type}, got {token.type} ({token.value}).")
        if expected_value and token.value != expected_value:
            raise FormulaError(f"Expected token value '{expected_value}', got '{token.value}'.")

        self.pos += 1
        return token

    def parse(self) -> ASTNode:
        # Start parsing at the lowest precedence level: expr
        node = self._parse_expr()

        if self.peek():
            raise FormulaError(f"Unexpected token remaining after parsing: {self.peek()}")

        return node

    # expr   := term {(+ | -) term} (Lowest precedence)
    def _parse_expr(self) -> ASTNode:
        node = self._parse_term()
        while self.peek() and self.peek().type in ('PLUS', 'MINUS'):
            op_token = self.consume()
            right = self._parse_term()
            node = BinaryOpNode(op_token.value, node, right)
        return node

    # term   := unary {(* | /) unary} (Medium precedence)
    def _parse_term(self) -> ASTNode:
        node = self._parse_unary()
        while self.peek() and self.peek().type in ('MUL', 'DIV'):
            op_token = self.consume()
            right = self._parse_unary()
            node = BinaryOpNode(op_token.value, node, right)
        return node

    # unary  := (+ | -) unary | number | ref | ( expr ) (Highest precedence)
    def _parse_unary(self) -> ASTNode:
        token = self.peek()
        if token and token.type in ('PLUS', 'MINUS'):
            op_token = self.consume()
            # Unary operator binds tighter than binary operators, so we recurse back to unary
            operand = self._parse_unary() 
            return UnaryOpNode(op_token.value, operand)

        if token and token.type == 'LPAREN':
            self.consume('LPAREN')
            node = self._parse_expr() # Inside parentheses, we parse full expressions
            self.consume('RPAREN')
            return node

        if token and token.type == 'NUMBER':
            self.consume('NUMBER')
            value_str = token.value
            # Rule 1: int if no '.', else float
            if '.' in value_str:
                return NumberNode(float(value_str))
            else:
                return NumberNode(int(value_str))

        elif token and token.type == 'REF':
            self.consume('REF')
            # References must be validated for format here
            ref_str = token.value.upper()
            # Validation checks (Column A-Z, Row 1-999, no leading zeros except for '0' which is invalid by specs)
            # Column check: 1 to 26 (A-Z)
            if not re.match(r'^[A-Z]{1,2}[1-9][0-9]{0,2}$', ref_str):
                # A simple check to catch things like AA1 (too long for single letter, but the grammar only allows letters, not more than 2 based on context, and the row must not have leading zeros)
                # Given the grammar `ref := letters digits`, and the sheet spec (A-Z, 1-999), we must ensure column count <= 1 and row format is correct.
                # A more precise check based on the specification constraints:
                # 1. Column letters: 1 to 26 (A-Z)
                # 2. Row number: 1 to 999, no leading zeros.

                col_letters = re.match(r'([A-Z]+)', ref_str).group(1)
                row_digits = re.match(r'([0-9]+)', ref_str).group(1)

                # Check for invalid column (more than 1 letter is disallowed by context, though grammar allows more)
                if len(col_letters) > 1:
                     raise FormulaError(f"Reference '{ref_str}' has too many column letters.")

                # Check for invalid row number format (leading zero or out of range)
                if len(row_digits) > 1 and row_digits.startswith('0'):
                    raise FormulaError(f"Reference '{ref_str}' has a leading zero in the row number.")

                row_num = int(row_digits)
                if not (1 <= row_num <= 999):
                    raise FormulaError(f"Reference '{ref_str}' is outside the valid row range (1-999).")

                # Column check: A-Z only
                if not re.match(r'^[A-Z]$', col_letters):
                     raise FormulaError(f"Reference '{ref_str}' has invalid column identifier.")

            return RefNode(ref_str)

        raise FormulaError(f"Unexpected token in unary position: {token}")

# --- Public Functions ---

def parse_formula(source: str) -> ASTNode:
    """Parses the text after '=' and returns a syntax tree."""
    if not source.strip():
        raise FormulaError("Formula source cannot be empty.")

    # The input `source` is the text AFTER the leading '=' sign.
    lexer = Lexer(source)
    tokens = lexer.get_tokens()

    parser = Parser(tokens)
    try:
        ast = parser.parse()
        # Final validation on the parsed tree (e.g., check for empty ref list if required, but standard grammar is satisfied)
        return ast
    except FormulaError as e:
        raise e
    except Exception as e:
        # Catching unexpected parsing errors and wrapping them as FormulaError
        raise FormulaError(f"Parsing failed due to an internal error: {e}")


def references(tree: ASTNode) -> Set[str]:
    """Returns the upper-case names of the cells the formula refers to."""
    refs: Set[str] = set()

    stack = [tree]
    while stack:
        node = stack.pop()

        if isinstance(node, RefNode):
            refs.add(node.name)
        elif isinstance(node, BinaryOpNode):
            stack.append(node.left)
            stack.append(node.right)
        elif isinstance(node, UnaryOpNode):
            stack.append(node.operand)

    return refs


def evaluate(tree: ASTNode, lookup: Callable[[str], CellValue]) -> CellValue:
    """Computes the formula's value."""

    # Helper to handle error propagation based on rule 3
    def handle_op(op: str, left_val: CellValue, right_val: CellValue) -> CellValue:
        # If either is an error value, the result is the left one (Rule 3)
        if isinstance(left_val, ErrorValue):
            return left_val
        if isinstance(right_val, ErrorValue):
            return right_val

        # If either is text, the result is #ERROR! (Rule 3)
        if isinstance(left_val, str) and not isinstance(left_val, ErrorValue):
            return ErrorValue("#ERROR!")
        if isinstance(right_val, str) and not isinstance(right_val, ErrorValue):
            return ErrorValue("#ERROR!")

        # Numeric/Arithmetic operations
        if op == '+':
            return left_val + right_val
        elif op == '-':
            return left_val - right_val
        elif op == '*':
            return left_val * right_val
        elif op == '/':
            # Division by zero check (Rule 4)
            if right_val == 0:
                return ErrorValue("#ERROR!")
            return left_val / right_val
        return ErrorValue("#ERROR!") # Should not happen

    # Helper to resolve operand values
    def resolve_operand(node: ASTNode) -> CellValue:
        if isinstance(node, NumberNode):
            return node.value

        if isinstance(node, RefNode):
            name = node.name
            cell_value = lookup(name)

            # Rule 2: Empty cell (None) gives 0
            if cell_value is None:
                return 0

            # Rule 2: Formula only reference returns text unchanged
            if isinstance(cell_value, str) and not isinstance(cell_value, ErrorValue):
                 # We assume if the formula *only* references a text cell, we return the text.
                 # This is tricky: the evaluation function must know if it's the *only* thing.
                 # Since we are evaluating a sub-tree, if the result is a string, it *must* be returned as is.
                return cell_value

            # Return actual value (int, float, or ErrorValue)
            return cell_value

        if isinstance(node, UnaryOpNode):
            operand_val = resolve_operand(node.operand)
            if isinstance(node.op, ('+', '-')):
                # Unary sign application
                if node.op == '+':
                    return operand_val
                else:
                    # Unary minus
                    if isinstance(operand_val, (int, float)):
                        return -operand_val
                    elif isinstance(operand_val, str) and not isinstance(operand_val, ErrorValue):
                        # Applying unary minus to text results in error
                        return ErrorValue("#ERROR!")
                    elif isinstance(operand_val, ErrorValue):
                        return operand_val
                    # If operand is None (resolved to 0), or if it's a special case not covered
                    return 0 - operand_val if isinstance(operand_val, (int, float)) else ErrorValue("#ERROR!")
            return ErrorValue("#ERROR!")

        if isinstance(node, BinaryOpNode):
            left_val = resolve_operand(node.left)
            right_val = resolve_operand(node.right)
            return handle_op(node.op, left_val, right_val)

        return ErrorValue("#ERROR!") # Should be unreachable

    # Start evaluation from the root
    return resolve_operand(tree)

