from typing import Dict, Optional, Any
from .versions import Version, Range

class PackageIndex:
    """Stores all available package releases and their dependency requirements."""

    def __init__(self):
        # Structure: {name: {Version: {dep_name: Range, ...}}}
        self._index: Dict[str, Dict[Version, Dict[str, Range]]] = {}

    def add(self, name: str, version_str: str, requires: Optional[Dict[str, str]] = None):
        """Adds a package release to the index."""
        # Version parsing and validation are assumed to be handled by caller or context if required
        try:
            version = Version(version_str)
        except ValueError as e:
            raise ValueError(f"Invalid version string '{version_str}' for {name}: {e}")

        if name not in self._index:
            self._index[name] = {}

        if version in self._index[name]:
            raise ValueError(f"Package {name} version {version_str} already exists in the index.")

        # Parse requirements strings into Range objects
        validated_requirements: Dict[str, Range] = {}
        if requires:
            for dep_name, spec_str in requires.items():
                try:
                    validated_requirements[dep_name] = Range(spec_str)
                except ValueError as e:
                    raise ValueError(f"Invalid range spec '{spec_str}' for dependency {dep_name} of {name}@{version_str}: {e}")

        self._index[name][version] = validated_requirements

    def versions(self, name: str) -> list[Version]:
        """Returns the list of known Versions for a package, newest first."""
        if name not in self._index:
            return []

        # Get all versions and sort them descending
        return sorted(self._index[name].keys(), reverse=True)

    def requirements(self, name: str, version: Version) -> Dict[str, Range]:
        """Returns a dict mapping each dependency name to its Range for a given Version."""
        if name not in self._index or version not in self._index[name]:
            raise KeyError(f"Version {version} of package {name} not found in index.")
        return self._index[name][version]

    @classmethod
    def from_dict(cls, data: Dict[str, Dict[str, Dict[str, str]]]) -> 'PackageIndex':
        """Builds an index from a dictionary structure."""
        index = cls()
        for name, versions_data in data.items():
            if name not in index._index:
                index._index[name] = {}

            for version_str, requirements_data in versions_data.items():
                try:
                    version = Version(version_str)
                except ValueError as e:
                    raise ValueError(f"Invalid version string '{version_str}' in input data for {name}: {e}")

                validated_requirements: Dict[str, Range] = {}
                for dep_name, spec_str in requirements_data.items():
                    try:
                        validated_requirements[dep_name] = Range(spec_str)
                    except ValueError as e:
                        raise ValueError(f"Invalid range spec '{spec_str}' in input data for {name}@{version_str}: {e}")

                index._index[name][version] = validated_requirements

        return index

