        # Operators: ==, !=, >=, <=, >, <, ^, ~
        # The pattern needs to capture the operator and the version number that follows.
        pattern = re.compile(r'([=<>!~^]+)?(\d+\.\d+\.\d+)')

        # First, handle the simple '*' constraint
        if '*' in spec:
            self.constraints.append(('*', None))
