            if not raw_c: continue

            # Check for '*' first
            if raw_c == '*':
                if ('*', None) not in self.constraints:
                    self.constraints.append(('*', None))
                continue

            # Check for explicit operators
            match = re.match(r'([<>=!~^]+)(.+)', raw_c)

            if match:
                op = match.group(1)
                version_str = match.group(2).strip()

                if not version_str: 
                    raise ValueError(f"Constraint '{raw_c}' is missing a version after operator '{op}'.")

                try:
                    version = self._parse_version_from_str(version_str)
                    self.constraints.append((op, version))
                except ValueError as e:
                    raise ValueError(f"Invalid version in constraint '{raw_c}': {e}")
            else:
                # If no operator, assume '==' if it looks like a version, or it's an error
                try:
                    version = self._parse_version_from_str(raw_c)
                    self.constraints.append(('==', version))
                except ValueError:
                    # If it doesn't parse as a version, it's an unknown operator/bad format
                    raise ValueError(f"Unknown operator or bad format in constraint: '{raw_c}'")

