        for op, required_v in self.constraints:
            if op == '*':
                continue # Always true

            if required_v is None: # Should only happen if '*' was the only constraint
                continue

            satisfied = False
            if op == '==':
                satisfied = (v == required_v)
            elif op == '!=':
                satisfied = (v != required_v)
            elif op == '>':
                satisfied = (v > required_v)
            elif op == '>=':
                satisfied = (v >= required_v)
            elif op == '<':
