class Range:
    """Represents a version constraint range."""

    def __init__(self, spec: str):
        self._spec = spec.strip()
        if not self._spec: 
            raise ValueError("Empty spec is not allowed.")

        self.constraints: List[Tuple[str, Version]] = []
        self._parse_spec(self._spec)

    def _parse_version_from_str(self, version_str: str) -> Version:
        """Helper to parse a version string safely."""
        return Version(version_str.strip())

    def _parse_spec(self, spec: str):
        # Replace all whitespace with nothing for initial tokenization
        spec_no_space = spec.replace(' ', '').replace(',', '')
        constraints_raw = [c.strip() for c in spec.split(',')] # Split by comma, preserving potential whitespace for now if we were to strictly follow original, but the requirement says whitespace around constraints is ignored.

        # Let's re-parse using splitting logic that accounts for operators
        # This is complex, let's use regex or careful iteration.

        import re
        # Regex to capture: (operator)(version) OR * or just version if it's ==
        # Operators: ==, !=, >=, <=, >, <, ^, ~
        # The pattern needs to capture the operator and the version number that follows.
        pattern = re.compile(r'([=<>!~^]+)?(\d+\.\d+\.\d+)')

        # First, handle the simple '*' constraint
        if '*' in spec:
            self.constraints.append(('*', None))
            # Remove * from further parsing if present
            spec = spec.replace('*', '').strip()

        # Split by comma first, then process each constraint
        raw_constraints = [c.strip() for c in spec.split(',')] # Re-splitting based on commas

        for raw_c in raw_constraints:
            raw_c = raw_c.strip()
            if not raw_c: continue

            # Check for '*' first
            if raw_c == '*':
                if ('*', None) not in self.constraints:
                    self.constraints.append(('*', None))
                continue

            # Check for explicit operators
            match = re.match(r'([<>=!~^]+)(.+)', raw_c)

            if match:
                op = match.group(1)
                version_str = match.group(2).strip()

                if not version_str: 
                    raise ValueError(f"Constraint '{raw_c}' is missing a version after operator '{op}'.")

                try:
                    version = self._parse_version_from_str(version_str)
                    self.constraints.append((op, version))
                except ValueError as e:
                    raise ValueError(f"Invalid version in constraint '{raw_c}': {e}")
            else:
                # If no operator, assume '==' if it looks like a version, or it's an error
                try:
                    version = self._parse_version_from_str(raw_c)
                    self.constraints.append(('==', version))
                except ValueError:
                    # If it doesn't parse as a version, it's an unknown operator/bad format
                    raise ValueError(f"Unknown operator or bad format in constraint: '{raw_c}'")

        # Final validation: check for empty constraints if comma separation was used but resulted in empty strings after strip
        if not self.constraints and spec.strip() != '*':
             raise ValueError("Could not parse any valid constraints from the specification.")

    def contains(self, v: Version) -> bool:
        """Checks if the version v satisfies all constraints in the range."""
        for op, required_v in self.constraints:
            if op == '*':
                continue # Always true

            if required_v is None: # Should only happen if '*' was the only constraint
                continue

            satisfied = False
            if op == '==':
                satisfied = (v == required_v)
            elif op == '!=':
                satisfied = (v != required_v)
            elif op == '>':
                satisfied = (v > required_v)
            elif op == '>=':
                satisfied = (v >= required_v)
            elif op == '<':
                satisfied = (v < required_v)
            elif op == '<=':
                satisfied = (v <= required_v)
            elif op == '^':
                # Caret: >= X.Y.Z, < (X+1).0.0 if X>0, or < X.(Y+1).0 if X=0, Y>0, etc.
                # Rule: ^1.2.3 is >=1.2.3, <2.0.0
                # Rule: ^0.2.3 is >=0.2.3, <0.3.0
                # Rule: ^0.0.3 is >=0.0.3, <0.0.4
                # Rule: ^0.0.0 is >=0.0.0, <0.0.1

                if required_v.major > 0:
                    next_major = required_v.major + 1
                    upper_bound = Version(f"{next_major}.0.0")
                    satisfied = (v >= required_v) and (v < upper_bound)
                else: # Major is 0 (e.g., ^0.2.3)
                    if required_v.minor > 0:
                        next_minor = required_v.minor + 1
                        upper_bound = Version(f"0.{next_minor}.0")
                        satisfied = (v >= required_v) and (v < upper_bound)
                    elif required_v.patch > 0:
                        next_patch = required_v.patch + 1
                        upper_bound = Version(f"0.0.{next_patch}")
                        satisfied = (v >= required_v) and (v < upper_bound)
                    else: # ^0.0.0 is >=0.0.0, <0.0.1
                        upper_bound = Version("0.0.1")
                        satisfied = (v >= required_v) and (v < upper_bound)

            elif op == '~':
                # Tilde: >= X.Y.Z, < X.(Y+1).0
                # Rule: ~1.2.3 is >=1.2.3, <1.3.0
                if required_v.patch >= 0: # Always true for valid versions
                    next_patch_val = required_v.patch + 1
                    upper_bound = Version(f"{required_v.major}.{required_v.minor}.{next_patch_val}")
                    satisfied = (v >= required_v) and (v < upper_bound)
                else: # Should not happen
                    satisfied = False

            if not satisfied:
                return False
        return True

    def __contains__(self, v: Version) -> bool:
        return self.contains(v)

    def __invert__(self) -> 'Range':
        # Support 'not in' conceptually, although not strictly required for the main task, it's good practice.
        # This implementation is complex for simple negation, so we focus only on the required interface.
        raise NotImplementedError("Negation of Range is not implemented.")

    def __str__(self) -> str:
        # Return the spec with all whitespace removed
        return self._spec.replace(' ', '').replace(',', '')

