class PackageIndex:
    """Manages the repository data for package resolutions.

    Stores available releases for packages and their dependencies.
    """
    def __init__(self):
        # Structure: {package_name: {version_string: {'requires': {dep_name: Range}, 'version_obj': Version}}}
        self.packages: Dict[str, Dict[str, Dict[str, Any]]] = {}

    def add(self, name: str, version_str: str, requires: Optional[Dict[str, str]] = None) -> None:
        """Adds a release for a package.

        Args:
            name: The name of the package.
            version_str: The version string (e.g., '1.2.3').
            requires: Optional dictionary mapping dependency names to range specs.
        Raises: 
            ValueError: If the version string is invalid, the name/version pair already exists, 
                        or the requirement spec is invalid.
        """
        if name not in self.packages:
            self.packages[name] = {}

        if version_str in self.packages[name]:
            raise ValueError(f"Version {version_str} for package {name} already exists.")

        version_obj = Version(version_str)

        if requires is None:
            requires = {}

        validated_requires: Dict[str, Range] = {}
        for dep_name, spec in requires.items():
            try:
                validated_requires[dep_name] = Range(spec)
            except ValueError as e:
                raise ValueError(f"Invalid range specification for dependency {dep_name} in {name}@{version_str}: {e}")

        self.packages[name][version_str] = {
            'requires': validated_requires,
            'version_obj': version_obj
        }

    def versions(self, name: str) -> list[Version]:
        """Returns the list of known Version objects for a package, newest first.

        Args:
            name: The name of the package.

        Returns:
            A list of Version objects, sorted descending by version.
        """ 
        if name not in self.packages:
            return []

        versions_data = self.packages[name]
        version_objects = [data['version_obj'] for data in versions_data.values()]
        # Sort by version comparison (descending)
        version_objects.sort(reverse=True)
        return version_objects

    def requirements(self, name: str, version_str: str) -> Dict[str, Range]:
        """Returns the dependency requirements for a specific version of a package.

        Args:
            name: The name of the package.
            version_str: The version string to check.

        Returns:
            A dictionary mapping dependency names to their Range objects.
        Raises:
            KeyError: If the package or version does not exist in the index.
        """
        if name not in self.packages:
            raise KeyError(f"Package {name} not found in index.")
        if version_str not in self.packages[name]:
            raise KeyError(f"Version {version_str} for package {name} not found in index.")

        return self.packages[name][version_str]['requires']

    @classmethod
    def from_dict(cls, data: Dict[str, Dict[str, Any]]) -> 'PackageIndex':
        """Builds an index from a dictionary structure.

        Args:
            data: Dictionary structure: {name: {version_str: {dep: spec, ...}, ...}, ...}

        Returns:
            A fully populated PackageIndex instance.
        Raises:
            ValueError: If any version or spec is invalid during bulk loading.
        """
        index = cls()
        for name, version_data in data.items():
            if not isinstance(version_data, dict):
                 raise ValueError(f"Data structure error: '{name}' does not contain a valid version dictionary.")
            for version_str, requirements in version_data.items():
                try:
                    # Temporarily use add logic to validate version and specs
                    # We pass None for requires here, as the input 'requirements' map already contains Range specs if built correctly, 
                    # but for safety we re-validate Range objects here.
                    validated_requires: Dict[str, Range] = {}
                    if isinstance(requirements, dict):
                        for dep_name, spec in requirements.items():
                            # Assuming spec is a string here based on the input dict structure
                            validated_requires[dep_name] = Range(spec)

                    index.packages[name][version_str] = {
                        'requires': validated_requires,
                        'version_obj': Version(version_str)
                    }
                except ValueError as e:
                    # Re-raise with context if validation fails during bulk loading
                    raise ValueError(f"Failed to load {name}@{version_str}: {e}")
