import re
import json
from dataclasses import dataclass, field
from datetime import datetime, timezone
from typing import Optional, Iterable, Tuple, List, Any

class ParseError(ValueError):
    """Raised when a log line cannot be parsed according to rules."""
    pass

@dataclass(frozen=True)
class Record:
    """Normalized log record."""
    time: datetime  # timezone-aware, in UTC
    client: str
    method: str
    path: str
    status: int
    size: int
    latency_ms: Optional[float]

# --- Helper functions ---

def _parse_time(time_str: str, fmt: str) -> datetime:
    """Parses a time string into a timezone-aware UTC datetime."""
    if fmt == 'clf':
        # Format: DD/Mon/YYYY:HH:MM:SS ±HHMM
        # Example: 10/Oct/2000:13:55:36 -0700
        try:
            dt = datetime.strptime(time_str, '%d/%b/%Y:%H:%M:%S %z')
            return dt.astimezone(timezone.utc)
        except ValueError as e:
            raise ParseError(f"Failed to parse CLF time '{time_str}': {e}")
    elif fmt == 'iso':
        # ISO 8601 format (can have offset or end in Z)
        try:
            # Handle Z suffix
            if time_str.endswith('Z'):
                time_str = time_str[:-1] + '+00:00'
            dt = datetime.fromisoformat(time_str)
            # If no offset was present, assume UTC (though spec implies offset presence)
            if dt.tzinfo is None or dt.tzinfo.utcoffset(dt) is None:
                return dt.replace(tzinfo=timezone.utc)
            return dt.astimezone(timezone.utc)
        except ValueError as e:
            raise ParseError(f"Failed to parse ISO time '{time_str}': {e}")
    else:
        raise ValueError(f"Unsupported time format: {fmt}")

def _normalize_value(value: Any, field_name: str, expected_type: str) -> Any:
    """Applies specific validation and transformation rules for a field."""
    if expected_type == 'client':
        if not isinstance(value, str) or not value.strip():
            raise ParseError(f"Client field must be a non-empty string.")
        return value.strip()

    elif expected_type == 'method':
        if not isinstance(value, str) or not value.strip() or not value.isalpha():
            raise ParseError(f"Method field must be a non-empty string of ASCII letters.")
        return value.upper()

    elif expected_type == 'path':
        if not isinstance(value, str) or not value.startswith('/'):
            raise ParseError(f"Path field must start with '/'.")
        # Remove everything from the first '?' or '#' on
        path = value.split('?')[0].split('#')[0]
        # Collapse runs of '/' into one
        return re.sub(r'/+', '/', path)

    elif expected_type == 'status':
        try:
            status_int = int(value) if isinstance(value, str) and value.isdigit() else int(value)
        except (ValueError, TypeError):
            raise ParseError(f"Status field must be convertible to an integer.")
        if 100 <= status_int <= 599:
            return status_int
        raise ParseError(f"Status code {status_int} is out of range (100-599).")

    elif expected_type == 'size':
        if value is None or value == '-':
            return 0
        try:
            return int(value) if isinstance(value, str) and value.isdigit() else int(value)
        except (ValueError, TypeError):
            raise ParseError(f"Size field must be a non-negative integer or '-'.")

    elif expected_type == 'latency_ms':
        if value is None: 
            return None
        try:
            return float(value) if isinstance(value, (str, int, float)) else None
        except (ValueError, TypeError):
            raise ParseError(f"Latency field must be a non-negative number or None.")

    return value

def normalize(time: datetime, client: str, method: str, path: str, status: int, size: int, latency_ms: Optional[float]) -> Record:
    """Applies validation and normalization rules to create a Record."""
    # All components are assumed to have passed their individual checks or are already correct
    return Record(
        time=time,
        client=client,
        method=method,
        path=path,
        status=status,
        size=size,
        latency_ms=latency_ms
    )

# --- CLF Parser ---

def parse_clf(line: str) -> Record:
    """Parses a line in Apache Common Log Format."""
    # Regex adapted for: client ident user [time] "method path protocol" status size [latency] 
    # Note: We capture the raw latency field if present, which might be microseconds.
    clf_regex = re.compile(r"(\S+) \S+ \S+ \[([^\]]+)\] ""([A-Z]+) (.*?) HTTP/\d\.\d"" (\d+) (\S+)(?: (\d+))?")
    match = clf_regex.match(line)

    if not match:
        raise ParseError("Line does not match CLF format.")

    client, time_str, method, path, status_str, size_str, latency_str = match.groups() or ((), (), (), (), (), (), ()) 

    # 1. Parse Time
    try:
        time_utc = _parse_time(time_str, 'clf')
    except ParseError as e:
        raise ParseError(f"CLF time parsing error: {e}")

    # 2. Normalize Fields
    try:
        client_norm = _normalize_value(client, 'client', 'client')
        method_norm = _normalize_value(method, 'method', 'method')
        path_norm = _normalize_value(path, 'path', 'path')
        status_norm = _normalize_value(status_str, 'status', 'status')
        size_norm = _normalize_value(size_str, 'size', 'size')

        latency_ms = None
        if latency_str is not None and latency_str.isdigit():
            # Latency is in microseconds, convert to milliseconds
            latency_ms = float(latency_str) / 1000.0

    except ParseError as e:
        raise ParseError(f"CLF field validation error: {e}")

    return normalize(time_utc, client_norm, method_norm, path_norm, status_norm, size_norm, latency_ms)

# --- JSONL Parser ---

def parse_jsonl(line: str) -> Record:
    """Parses a line in JSON Lines format."""
    try:
        data: dict[str, Any] = json.loads(line)
    except json.JSONDecodeError as e:
        raise ParseError(f"Invalid JSON: {e}")

    required_keys = ['ts', 'client', 'method', 'path', 'status']
    if not all(key in data for key in required_keys):
        raise ParseError(f"Missing required keys in JSON record. Required: {required_keys}")

    # 1. Parse Time
    try:
        time_utc = _parse_time(data['ts'], 'iso')
    except ParseError as e:
        raise ParseError(f"JSON time parsing error: {e}")

    # 2. Normalize Fields
    try:
        client_norm = _normalize_value(data['client'], 'client', 'client')
        method_norm = _normalize_value(data['method'], 'method', 'method')
        path_norm = _normalize_value(data['path'], 'path', 'path')
        status_norm = _normalize_value(data['status'], 'status', 'status')

        # Size handling: bytes key in JSONL
        size_norm = _normalize_value(data.get('bytes'), 'size', 'size')

        # Latency handling: latency_ms key in JSONL
        latency_ms = _normalize_value(data.get('latency_ms'), 'latency_ms', 'latency_ms')

    except ParseError as e:
        raise ParseError(f"JSON field validation error: {e}")

    return normalize(time_utc, client_norm, method_norm, path_norm, status_norm, size_norm, latency_ms)

# --- Dispatcher ---

def parse_line(line: str, fmt: str = 'auto') -> Record:
    """Dispatches parsing based on format or heuristic."""
    line = line.strip()
    if not line:
        raise ParseError("Empty line passed to parse_line.")

    if fmt == 'clf':
        return parse_clf(line)
    elif fmt == 'jsonl':
        return parse_jsonl(line)
    elif fmt == 'auto':
        # Heuristic: If it starts with '{', assume JSONL
        if line.startswith('{') and line.endswith('}'):
            return parse_jsonl(line)
        else:
            # Otherwise, assume CLF
            return parse_clf(line)
    else:
        raise ValueError(f"Unsupported format '{fmt}'. Must be 'clf', 'jsonl', or 'auto'.")

def read_records(lines: Iterable[str], fmt: str = 'auto') -> Tuple[List[Record], List[int]]:
    """Reads an iterable of lines and returns parsed records and line numbers with errors."""
    records: List[Record] = []
    bad_lines: List[int] = []

    for i, line in enumerate(lines, 1):
